// =====================================================================
// BLOCO 1 | INTERPRETAR MENSAGEM DO TELEGRAM (conversa progressiva)
// Recebe o "Update" do Telegram (mesmo formato da API oficial) + o estado da conversa
// salvo no PostgreSQL. Decide a ação:
//   "ignorar"   -> update repetido ou sem mensagem (nada a responder)
//   "responder" -> comandos /start, /ajuda, /cancelar (resposta direta, sem demanda)
//   "processar" -> monta o envelope e segue para o pipeline comum do HUB
// A extração de campos NÃO é repetida aqui: o pipeline comum extrai, valida e, se faltar
// dado, o node "Perguntar Próximo Dado" pede ao usuário UM campo por vez.
// =====================================================================

const update = $('Webhook Telegram').first().json.body || {};
const conversa = $input.first().json.conversa || {};
const estado = conversa.estado || {};
const msg = update.message || update.edited_message || null;

const BOAS_VINDAS = [
  'Olá! Aqui é o Rodomax HUB.',
  '',
  'Você pode enviar:',
  '• um pedido de FRETE — ex.: "Preciso transportar milho do PR para Toledo"',
  '• qualquer outra solicitação (financeiro, cadastro, atendimento...) — ex.: "Preciso da segunda via do boleto"',
  '',
  'Se faltar alguma informação, eu pergunto. Comandos: /cancelar (recomeçar) e /ajuda.',
].join('\n');

const saida = (dados) => [{ json: { update_id: update.update_id ?? null, ...dados } }];

if (!msg || !msg.chat) return saida({ acao: 'ignorar', chat_id: null, texto: null, motivo: 'update sem mensagem' });
const chatId = msg.chat.id;
if (conversa.ultimo_update && update.update_id && Number(update.update_id) <= Number(conversa.ultimo_update)) {
  return saida({ acao: 'ignorar', chat_id: chatId, texto: null, motivo: 'update já processado (duplicado)' });
}
if (typeof msg.text !== 'string' || !msg.text.trim()) {
  return saida({ acao: 'responder', chat_id: chatId, estado, texto: 'Por enquanto eu só entendo mensagens de texto. Descreva sua solicitação em uma mensagem.' });
}

const textoMsg = msg.text.trim();
const comando = textoMsg.toLowerCase().split(/\s|@/)[0];
if (['/start', '/ajuda', '/help'].includes(comando)) return saida({ acao: 'responder', chat_id: chatId, estado: {}, texto: BOAS_VINDAS });
if (/^(oi|ola|olá|opa|bom dia|boa tarde|boa noite|e ai|e aí|hello|hi)[!.?\s]*$/i.test(textoMsg) && !estado.aguardando) return saida({ acao: 'responder', chat_id: chatId, estado: {}, texto: BOAS_VINDAS });
if (['/cancelar', '/cancel'].includes(comando)) return saida({ acao: 'responder', chat_id: chatId, estado: {}, texto: 'Conversa cancelada. Quando quiser, envie uma nova solicitação.' });

// ----- acumula a conversa -----
const nome = [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || msg.chat.title || 'Usuário do Telegram';
const campos = { ...(estado.campos || {}) };
let textos = [...(estado.textos || [])];
// resposta curta a uma pergunta feita -> vale para o campo perguntado; texto longo -> vai para o texto livre
if (estado.aguardando && textoMsg.length <= 40) campos[estado.aguardando] = textoMsg;
else textos.push(textoMsg);
textos = textos.slice(-10);

return saida({
  acao: 'processar',
  chat_id: chatId,
  envelope: {
    canal: 'telegram',
    chave_evento: `telegram:${update.update_id}`,
    solicitante: { nome, telegram_chat_id: chatId, telegram_usuario: msg.from?.username || null },
    tipo_informado: estado.tipo || null,
    assunto: '',
    texto: textos.join('\n'),
    campos_brutos: campos,
    dados_originais: { mensagens: textos, respostas: campos, ultimo_update: update.update_id, de: { id: msg.from?.id, username: msg.from?.username || null } },
    resposta: { via: 'telegram', chat_id: chatId, update_id: update.update_id },
    telegram: { chat_id: chatId, update_id: update.update_id, estado_anterior: estado },
  },
});

// =====================================================================
// BLOCO 1 | PREPARAR E-MAIL RECEBIDO (Email Trigger IMAP — formato "simple")
// • Lê remetente, assunto e corpo; preserva o conteúdo original.
// • NÃO presume que todo e-mail é frete: o tipo é decidido depois (geral x logística).
// • Ignora respostas automáticas (no-reply, mailer-daemon, "Auto-Submitted") para não
//   criar laço de respostas entre robôs.
// • Primeiro anexo PDF -> binário "data", para o node "Extrair Texto do PDF".
// =====================================================================

const texto = (v) => (v === null || v === undefined ? '' : String(v));
// "Nome <email@x.com>" -> { nome, email } (aceita também o formato "resolved" do n8n)
function lerRemetente(from) {
  if (from && typeof from === 'object' && Array.isArray(from.value)) return { nome: texto(from.value[0]?.name), email: texto(from.value[0]?.address) };
  const m = texto(from).match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>\s*$/);
  return m ? { nome: m[1].trim(), email: m[2].trim() } : { nome: '', email: texto(from).trim() };
}
const semHtml = (h) => texto(h).replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/[ \t]+/g, ' ').trim();
// TXT/PDF/e-mail: linhas "Chave: valor" viram campos
function lerChaveValor(conteudo) {
  const campos = {};
  for (const linha of texto(conteudo).split(/\r?\n/)) {
    const m = linha.match(/^\s*([A-Za-zÀ-ÿ /()_-]{2,40}):\s*(.+)$/);
    if (m) campos[m[1].trim()] = m[2].trim();
  }
  return campos;
}

const saida = [];
for (const item of $input.all()) {
  const j = item.json;
  const rem = lerRemetente(j.from);
  const meta = j.metadata || j.headers || {};
  const autoSubmitted = texto(meta['auto-submitted'] || '').toLowerCase();
  const assunto = texto(j.subject).trim();
  const corpo = (texto(j.textPlain || j.text).trim() || semHtml(j.textHtml || j.html)).slice(0, 10000);

  // filtro anti-laço: mensagens automáticas não geram demanda nem resposta
  if (/no-?reply|mailer-daemon|postmaster/i.test(rem.email) || (autoSubmitted && autoSubmitted !== 'no')) continue;

  // primeiro anexo PDF vira o binário "data"
  const binarios = item.binary || {};
  const chavePdf = Object.keys(binarios).find((k) => /pdf/i.test(binarios[k].mimeType || '') || /\.pdf$/i.test(binarios[k].fileName || ''));
  const anexos = Object.values(binarios).map((b) => b.fileName).filter(Boolean);
  const messageId = texto(meta['message-id'] || j.messageId || '').trim();

  saida.push({
    json: {
      canal: 'email',
      chave_evento: `email:${messageId || (rem.email + '|' + assunto + '|' + texto(j.date))}`,
      solicitante: { nome: rem.nome, email: rem.email },
      assunto,
      texto: corpo,
      campos_brutos: lerChaveValor(corpo),
      dados_originais: { de: texto(j.from?.text || j.from), assunto, data: texto(j.date), corpo, anexos, message_id: messageId },
      resposta: { via: 'email', email: rem.email, assunto: assunto ? `Re: ${assunto}` : 'Rodomax HUB — sua solicitação' },
      tem_pdf: !!chavePdf,
      arquivo: chavePdf ? { nome: binarios[chavePdf].fileName, mime: binarios[chavePdf].mimeType, finalidade: 'documento' } : null,
    },
    binary: chavePdf ? { data: binarios[chavePdf] } : undefined,
  });
}
return saida;

// =====================================================================
// BLOCO 1 | RECEBER PDF
// Duas origens chegam aqui:
//   • Webhook Upload PDF (aplicação web): binário "data" + campos opcionais do formulário
//   • Anexo PDF de e-mail (node "Preparar E-mail"): já é um envelope de canal "email"
// Confere nome/tipo do arquivo e repassa o binário para a extração de texto.
// =====================================================================

const texto = (v) => (v === null || v === undefined ? '' : String(v));
return $input.all().map((item, i) => {
  const j = item.json;
  const bin = (item.binary || {}).data;
  if (j.canal === 'email') return { json: j, binary: item.binary, pairedItem: { item: i } };

  const b = j.body || {};
  const nome = bin ? texto(bin.fileName) : '';
  const ehPdf = !!bin && (/pdf/i.test(texto(bin.mimeType)) || /\.pdf$/i.test(nome));
  return {
    json: {
      canal: 'pdf',
      chave_evento: b.id_requisicao ? `pdf:${b.id_requisicao}` : null,
      solicitante: { nome: texto(b.nome).trim(), email: texto(b.email).trim(), telefone: texto(b.telefone).trim() },
      tipo_informado: b.tipo_demanda || null,
      assunto: '',
      texto: '',
      campos_brutos: {},
      dados_originais: {},
      resposta: { via: 'http' },
      arquivo: { nome: nome || 'sem_nome.pdf', mime: bin ? bin.mimeType : null, tamanho: b.tamanho_bytes || null, finalidade: 'documento', eh_pdf: ehPdf },
    },
    binary: item.binary,
    pairedItem: { item: i },
  };
});

// =====================================================================
// BLOCO 3 | LER TEXTO DO PDF
// Junta o texto extraído (node "Extrair Texto do PDF") ao envelope de origem.
// • PDF sem texto (escaneado/imagem) ou corrompido: a situação é informada e NADA
//   é inventado. OCR não faz parte desta versão.
// • Linhas "Chave: valor" viram campos; o restante vira texto livre (extraído depois).
// Saída: { arquivo_registro (para hub_arquivos), envelope (segue no pipeline) }
// =====================================================================

const texto = (v) => (v === null || v === undefined ? '' : String(v));
function lerChaveValor(conteudo) {
  const campos = {};
  for (const linha of texto(conteudo).split(/\r?\n/)) {
    const m = linha.match(/^\s*([A-Za-zÀ-ÿ /()_-]{2,40}):\s*(.+)$/);
    if (m) campos[m[1].trim()] = m[2].trim();
  }
  return campos;
}

const origens = $('Receber PDF').all();
return $input.all().map((item, i) => {
  const env = { ...origens[i].json };
  const ext = item.json || {};
  const erro = ext.error ? texto(ext.error.message || ext.error) : null;
  const conteudo = texto(ext.text).replace(/\u0000/g, '').trim();
  const legivel = !erro && conteudo.replace(/\s/g, '').length >= 10;
  const status = erro ? 'erro' : legivel ? 'recebido' : 'sem_texto';
  const detalhe = erro ? `Falha na extração: ${erro}` : legivel ? `${ext.numpages || '?'} página(s), ${conteudo.length} caracteres extraídos`
    : 'PDF sem texto extraível (provavelmente escaneado/imagem). OCR não faz parte desta versão.';

  const campos = legivel ? lerChaveValor(conteudo) : {};
  if (env.canal === 'email') {
    // e-mail: o texto do anexo complementa o corpo da mensagem
    if (legivel) { env.texto = [env.texto, conteudo].filter(Boolean).join('\n\n'); env.campos_brutos = { ...campos, ...env.campos_brutos }; }
    env.dados_originais = { ...env.dados_originais, texto_anexo_pdf: legivel ? conteudo.slice(0, 5000) : null };
  } else {
    env.texto = conteudo.slice(0, 10000);
    env.campos_brutos = campos;
    env.dados_originais = { arquivo: env.arquivo.nome, texto_extraido: conteudo.slice(0, 5000), formulario: env.solicitante };
  }
  env.eventos = [{ etapa: 'pdf', detalhe: `${env.arquivo.nome}: ${detalhe}` }];
  env.pdf_legivel = env.canal === 'email' ? true : legivel;   // e-mail ainda tem o corpo da mensagem
  env.pdf_detalhe = detalhe;

  return {
    json: {
      arquivo_registro: {
        nome_arquivo: env.arquivo.nome, tipo_arquivo: 'pdf', finalidade: 'documento', canal: env.canal,
        tamanho_bytes: Number(env.arquivo.tamanho) || null,
        registros_total: legivel ? 1 : 0, status, texto_extraido: legivel ? conteudo : null, detalhe,
      },
      envelope: env,
    },
    pairedItem: { item: i },
  };
});

// =====================================================================
// BLOCO 3 | LER CSV  (evolução do leitor de CSV da 1ª etapa)
// • Detecta o separador (; , ou TAB) pelo cabeçalho e respeita aspas (inclusive quebras de linha).
// • Cabeçalhos são padronizados ("Distância (km)" -> "distancia_km").
// • Distingue a FINALIDADE da importação (escolhida na interface):
//     "historico"       -> base ROTULADA para treino/avaliação: exige a coluna "atendida"
//     "novas_demandas"  -> demandas novas para processamento: "atendida" NÃO é exigida
//                          (se vier, é ignorada, pois é exatamente o que a IA vai prever)
// • 1 arquivo = 1 lote: registros_total conta LINHAS de dados, não arquivos.
// Saída: { arquivo_registro (hub_arquivos), envelope (linhas + metadados) }
// =====================================================================

const texto = (v) => (v === null || v === undefined ? '' : String(v));
const chave = (k) => String(k).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
function fnv(txt, seed) { let h = seed; for (const ch of txt) { h ^= ch.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }
const hash = (txt) => fnv(txt, 0x811c9dc5) + fnv(txt, 0x9747b28c);

const COLUNAS_HISTORICO = ['produto', 'uf_origem', 'destino', 'distancia_km', 'frete_ton', 'saldo_ton', 'balanca', 'estrada_chao_km', 'antecedencia_h', 'atendida'];

// Parser CSV simples e correto: aspas duplas, "" escapado, separador e quebras de linha dentro de aspas
function parseCsv(conteudo, sep) {
  const linhas = []; let campo = ''; let linha = []; let aspas = false;
  for (let i = 0; i < conteudo.length; i++) {
    const ch = conteudo[i];
    if (aspas) {
      if (ch === '"' && conteudo[i + 1] === '"') { campo += '"'; i++; }
      else if (ch === '"') aspas = false;
      else campo += ch;
    } else if (ch === '"') aspas = true;
    else if (ch === sep) { linha.push(campo); campo = ''; }
    else if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && conteudo[i + 1] === '\n') i++;
      linha.push(campo); campo = '';
      if (linha.some((c) => c.trim() !== '')) linhas.push(linha);
      linha = [];
    } else campo += ch;
  }
  linha.push(campo);
  if (linha.some((c) => c.trim() !== '')) linhas.push(linha);
  return linhas;
}

const b = $input.first().json.body || {};
const nome = texto(b.nome_arquivo).trim() || 'sem_nome.csv';
const finalidade = ['historico', 'novas_demandas'].includes(b.finalidade) ? b.finalidade : null;
const conteudo = texto(b.conteudo).replace(/^\uFEFF/, '');   // remove BOM do Excel
const primeira = conteudo.split(/\r?\n/)[0] || '';
const contagem = { ';': (primeira.match(/;/g) || []).length, ',': (primeira.match(/,/g) || []).length, '\t': (primeira.match(/\t/g) || []).length };
const sep = Object.keys(contagem).sort((x, y) => contagem[y] - contagem[x])[0];

let erro = null; let aviso = null;
const tabela = conteudo.trim() ? parseCsv(conteudo, sep) : [];
const cabecalhos = (tabela[0] || []).map((c) => chave(c));
const linhas = tabela.slice(1).map((v, i) => ({ linha: i + 2, campos: Object.fromEntries(cabecalhos.map((c, k) => [c, texto(v[k]).trim()])) }));

if (!finalidade) erro = 'Finalidade da importação não informada (use "historico" ou "novas_demandas").';
else if (!conteudo.trim()) erro = 'Arquivo CSV vazio.';
else if (cabecalhos.length < 2) erro = 'Não foi possível identificar colunas: verifique o separador (; ou ,).';
else if (!linhas.length) erro = 'CSV sem linhas de dados (apenas cabeçalho).';
else if (finalidade === 'historico') {
  const faltam = COLUNAS_HISTORICO.filter((c) => !cabecalhos.includes(c));
  if (faltam.length) erro = `Base histórica precisa das colunas: ${faltam.join(', ')}. Para demandas novas (sem "atendida"), escolha a finalidade "Novas demandas".`;
} else if (cabecalhos.includes('atendida')) {
  aviso = 'A coluna "atendida" foi recebida em demandas novas e será ignorada (é o que a IA prevê). Para treinar o modelo, importe como "Base histórica".';
}

const detalhe = erro || [`${linhas.length} linha(s) de dados, separador "${sep === '\t' ? 'TAB' : sep}"`, aviso].filter(Boolean).join('. ');
return [{ json: {
  arquivo_registro: {
    nome_arquivo: nome, tipo_arquivo: 'csv', finalidade: finalidade || 'novas_demandas', canal: 'web',
    tamanho_bytes: Number(b.tamanho_bytes) || conteudo.length, hash_conteudo: hash(conteudo), separador: sep === '\t' ? 'TAB' : sep,
    cabecalhos, registros_total: linhas.length, status: erro ? 'erro' : 'recebido', detalhe,
  },
  envelope: {
    csv_ok: !erro, erro, aviso, finalidade, nome_arquivo: nome, separador: sep, cabecalhos,
    hash_conteudo: hash(conteudo), linhas, solicitante: { nome: texto(b.nome).trim(), email: texto(b.email).trim() },
  },
} }];

// =====================================================================
// BLOCO IA | VALIDAR BASE HISTÓRICA (CSV com finalidade "historico")
// Confere cada linha antes de gravar em ia_historico. Os valores NÃO são alterados
// (só convertidos para número/minúsculas onde o tipo exige). Linhas com problema são
// rejeitadas e CONTADAS, com o motivo — nunca descartadas em silêncio.
// =====================================================================

const env = $input.first().json.envelope;
const NUM = ['distancia_km', 'frete_ton', 'saldo_ton', 'estrada_chao_km', 'antecedencia_h'];
const TXT = ['produto', 'uf_origem', 'destino', 'balanca'];
const validos = []; const rejeitados = []; const ids = new Set();

for (const { linha, campos: c } of env.linhas) {
  const motivos = [];
  const id = Number(c.id_demanda);
  if (!Number.isInteger(id) || id <= 0) motivos.push('id_demanda ausente ou inválido');
  else if (ids.has(id)) motivos.push(`id_demanda ${id} repetido no arquivo`);
  const reg = { id_demanda: id, canal: c.canal || null, status_agendamento: c.status_agendamento || null };
  for (const k of NUM) {
    const v = c[k] === '' || c[k] === undefined ? NaN : Number(String(c[k]).replace(',', '.'));
    if (Number.isNaN(v) || v < 0) motivos.push(`${k} inválido: "${c[k] ?? ''}"`); else reg[k] = v;
  }
  for (const k of TXT) { if (!c[k]) motivos.push(`${k} ausente`); else reg[k] = c[k]; }
  const at = String(c.atendida || '').trim().toLowerCase();
  if (!['sim', 'nao'].includes(at)) motivos.push(`atendida deve ser "sim" ou "nao": "${c.atendida ?? ''}"`); else reg.atendida = at;

  if (motivos.length) rejeitados.push({ linha, motivos });
  else { validos.push(reg); ids.add(id); }
}

return [{ json: {
  arquivo_id: env.arquivo_id,
  nome_arquivo: env.nome_arquivo,
  registros: validos,
  total_linhas: env.linhas.length,
  rejeitados: rejeitados.length,
  exemplos_rejeicao: rejeitados.slice(0, 20),
} }];

// =====================================================================
// BLOCO 2 | EXPANDIR LINHAS DO CSV (finalidade "novas_demandas")
// Cada linha do arquivo vira UMA solicitação (envelope) que segue o pipeline comum.
// O vínculo com o arquivo (arquivo_id + número da linha) é preservado.
// A coluna "atendida", se existir, NÃO é usada como atributo (ver Auditar e Validar).
// =====================================================================

const env = $input.first().json.envelope;
return env.linhas.map((l, i) => ({
  json: {
    canal: 'csv',
    // mesmo conteúdo reenviado => mesma chave => não duplica (o registro original é mantido)
    chave_evento: `csv:${env.hash_conteudo}:${l.linha}`,
    solicitante: { nome: env.solicitante?.nome || '', email: env.solicitante?.email || '' },
    tipo_informado: l.campos.tipo_demanda || null,
    assunto: '',
    texto: '',
    campos_brutos: l.campos,
    dados_originais: { arquivo: env.nome_arquivo, linha: l.linha, colunas: l.campos },
    arquivo_id: env.arquivo_id,
    linha_arquivo: l.linha,
    resposta: { via: 'lote' },
  },
  pairedItem: { item: 0 },
}));

// =====================================================================
// BLOCO 2 | CONSOLIDAR ENTRADA  (adaptado do node "Consolidar e Extrair" da 1ª etapa)
// Recebe itens de TODOS os canais e devolve um ENVELOPE PADRÃO por solicitação:
//   { canal, chave_evento, recebido_em, ambiente, solicitante, tipo_informado,
//     assunto, texto, campos_brutos, dados_originais, arquivo_id, linha_arquivo,
//     finalidade, resposta, eventos }
// • Itens do Telegram, e-mail, PDF, CSV e testes já chegam com "canal" (montados
//   pelos nodes de cada canal). Itens sem "canal" vieram do Webhook da aplicação web.
// • Nada é descartado aqui: entradas vazias seguem e serão tratadas na validação.
// • O conteúdo original é preservado em "dados_originais".
// =====================================================================

const texto = (v) => (v === null || v === undefined ? '' : String(v));

// Hash FNV-1a (2 sementes = 64 bits) — mesma função da 1ª etapa, usada para chaves determinísticas
function fnv(txt, seed) {
  let h = seed;
  for (const ch of txt) { h ^= ch.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}
const hash = (txt) => fnv(txt, 0x811c9dc5) + fnv(txt, 0x9747b28c);

// Corpo do webhook como objeto (aceita JSON ou texto puro)
function corpo(json) {
  let b = json.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = { mensagem: b }; } }
  return b && typeof b === 'object' && !Array.isArray(b) ? b : {};
}

const agora = new Date().toISOString();

return $input.all().map((item, i) => {
  let j = item.json;
  if (j.envelope && typeof j.envelope === 'object') j = j.envelope;   // vindo do node PostgreSQL de arquivo

  let env;
  if (j.canal) {
    env = { ...j };                                                   // já é um envelope de canal
  } else {
    // ---- Aplicação web (formulários de frete e de demanda geral) ----
    const b = corpo(j);
    const { id_requisicao, tipo_demanda, nome, email, telefone, assunto, descricao, ...resto } = b;
    env = {
      canal: 'web',
      chave_evento: id_requisicao ? `web:${texto(id_requisicao)}` : null,
      solicitante: { nome: texto(nome).trim(), email: texto(email).trim(), telefone: texto(telefone).trim() },
      tipo_informado: tipo_demanda || null,
      assunto: texto(assunto).trim(),
      texto: texto(descricao).trim(),
      campos_brutos: { ...resto, ...(assunto ? { assunto } : {}), ...(descricao ? { descricao } : {}) },
      dados_originais: b,
      resposta: { via: 'http' },
    };
  }

  env.recebido_em = env.recebido_em || agora;
  env.ambiente = env.ambiente || 'demonstracao';
  env.solicitante = env.solicitante || {};
  env.campos_brutos = env.campos_brutos || {};
  env.dados_originais = env.dados_originais || env.campos_brutos;
  env.eventos = [...(env.eventos || []), { etapa: 'recebido', detalhe: `Recebido pelo canal ${env.canal}` }];
  // Sem identificador do evento: gera um a partir do conteúdo + data (evita gravar duas vezes o mesmo envio)
  if (!env.chave_evento) {
    env.chave_evento = `${env.canal}:${hash(JSON.stringify(env.dados_originais) + '|' + env.recebido_em + '|' + i)}`;
  }
  return { json: env, pairedItem: { item: i } };
});

// =====================================================================
// BLOCO 3 | MAPEAR CAMPOS  (evolução do node "Mapear Campos" da 1ª etapa)
// 1) Reconhece nomes equivalentes (celular = fone = telefone; frete = frete_ton ...)
// 2) Quando o pedido chega como TEXTO LIVRE (Telegram, e-mail, PDF), extrai os campos
//    logísticos com expressões regulares simples. Só preenche o que está escrito:
//    nada é inventado. Campo não encontrado continua ausente.
// Saída: dados (campos canônicos), origem_dos_campos, campos_nao_mapeados, conflitos
// Os VALORES ainda não são convertidos aqui (isso é feito na validação/normalização).
// =====================================================================

const SINONIMOS = {
  // ---- campos gerais (1ª etapa) ----
  nome: ['nome', 'nome_cliente', 'cliente', 'nome_completo', 'razao_social', 'solicitante', 'name'],
  telefone: ['telefone', 'celular', 'fone', 'tel', 'whatsapp', 'phone', 'contato'],
  email: ['email', 'e_mail', 'mail'],
  documento: ['documento', 'cpf', 'cnpj', 'cpf_cnpj', 'doc'],
  data_pedido: ['data_pedido', 'data', 'data_solicitacao', 'data_do_pedido', 'dt_pedido'],
  tipo: ['tipo', 'assunto', 'motivo', 'tipo_solicitacao', 'subject', 'setor_desejado'],
  observacao: ['observacao', 'obs', 'mensagem', 'descricao', 'texto', 'detalhes', 'message', 'solicitacao'],
  nota_fiscal: ['nota_fiscal', 'nf', 'num_nf', 'nfe'],
  tipo_demanda: ['tipo_demanda', 'categoria_demanda'],
  // ---- campos logísticos (mesmos nomes do dataset rodomax_demandas.csv) ----
  produto: ['produto', 'carga', 'mercadoria', 'grao'],
  uf_origem: ['uf_origem', 'uf', 'origem_uf', 'estado_origem', 'origem', 'uf_de_origem'],
  destino: ['destino', 'cidade_destino', 'destino_cidade', 'entrega'],
  distancia_km: ['distancia_km', 'distancia', 'km', 'distancia_em_km'],
  frete_ton: ['frete_ton', 'frete', 'valor_frete', 'frete_por_tonelada', 'preco_ton', 'frete_r_ton', 'valor_do_frete'],
  saldo_ton: ['saldo_ton', 'saldo', 'toneladas', 'volume_ton', 'quantidade_ton', 'peso_ton', 'saldo_em_toneladas'],
  balanca: ['balanca', 'tipo_balanca', 'balanca_m', 'tipo_de_balanca'],
  estrada_chao_km: ['estrada_chao_km', 'estrada_chao', 'chao_km', 'estrada_terra_km', 'estrada_de_chao', 'km_estrada_de_chao'],
  antecedencia_h: ['antecedencia_h', 'antecedencia', 'antecedencia_horas', 'prazo_h', 'antecedencia_em_horas'],
  // ---- históricos (só são guardados; NÃO são usados como atributo da IA) ----
  id_demanda: ['id_demanda'],
  canal_historico: ['canal'],
  status_agendamento: ['status_agendamento'],
  atendida: ['atendida'],
};
const CAMPOS_LOGISTICOS = ['produto', 'uf_origem', 'destino', 'distancia_km', 'frete_ton', 'saldo_ton', 'balanca', 'estrada_chao_km', 'antecedencia_h'];

// "Nome Cliente" -> "nome_cliente" ; "Distância (km)" -> "distancia_km"
const chave = (k) => String(k).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().trim().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const PARA_CANONICO = {};
for (const [canonico, apelidos] of Object.entries(SINONIMOS)) apelidos.forEach((a) => { PARA_CANONICO[a] = canonico; });

// Dois valores "dizem a mesma coisa"? (telefone/documento/NF comparam só dígitos)
function mesmoValor(campo, a, b) {
  if (['telefone', 'documento', 'nota_fiscal'].includes(campo)) return a.replace(/\D/g, '') === b.replace(/\D/g, '');
  return chave(a) === chave(b);
}

// ----------------------- EXTRAÇÃO DE TEXTO LIVRE -----------------------
const UFS = ['AC', 'AL', 'AP', 'AM', 'BA', 'CE', 'DF', 'ES', 'GO', 'MA', 'MT', 'MS', 'MG', 'PA', 'PB', 'PR', 'PE', 'PI', 'RJ', 'RN', 'RS', 'RO', 'RR', 'SC', 'SP', 'SE', 'TO'];
const ESTADOS = { 'parana': 'PR', 'mato grosso do sul': 'MS', 'mato grosso': 'MT', 'santa catarina': 'SC', 'sao paulo': 'SP', 'rio grande do sul': 'RS', 'goias': 'GO', 'minas gerais': 'MG' };
const PRODUTOS = ['milho', 'soja', 'trigo', 'sorgo', 'farelo', 'arroz', 'feijao', 'cafe', 'algodao'];
const CIDADES_CONHECIDAS = ['Paranagua', 'Toledo', 'Maringa', 'Xanxere', 'Lacerdopolis', 'Cascavel', 'Guarapuava', 'Videira'];
const NUM = '(\\d{1,3}(?:\\.\\d{3})+(?:,\\d+)?|\\d+(?:[.,]\\d+)?)';

function extrairDoTexto(textoOriginal) {
  const t = semAcento(textoOriginal);           // mantém maiúsculas (para UF)
  const low = t.toLowerCase();
  const achados = {};
  let m;

  // produto
  const prod = PRODUTOS.find((p) => new RegExp(`\\b${p}\\b`).test(low));
  if (prod) achados.produto = prod.toUpperCase();

  // estrada de chão: "12 km de estrada de chão", "estrada de chão: 12", "sem estrada de chão"
  if ((m = low.match(new RegExp(`${NUM}\\s*km\\s*(?:de\\s+)?(?:estrada\\s+de\\s+)?(?:chao|terra)`)))) achados.estrada_chao_km = m[1];
  else if ((m = low.match(new RegExp(`(?:estrada\\s+de\\s+)?(?:chao|terra)\\s*(?:de|:|=)?\\s*${NUM}`)))) achados.estrada_chao_km = m[1];
  else if (/sem\s+(?:estrada\s+de\s+)?(?:chao|terra)|(?:tudo|so|somente)\s+(?:no\s+)?asfalto/.test(low)) achados.estrada_chao_km = '0';

  // distância: "450 km" (que NÃO seja de estrada de chão) ou "distância: 450"
  if ((m = low.match(new RegExp(`distancia\\s*(?:de|:|=)?\\s*${NUM}`)))) achados.distancia_km = m[1];
  else {
    const re = new RegExp(`${NUM}\\s*(?:km|quilometros)\\b(?!\\s*(?:de\\s+)?(?:estrada\\s+de\\s+)?(?:chao|terra))`, 'g');
    const r = re.exec(low);
    if (r) achados.distancia_km = r[1];
  }

  // frete por tonelada: "frete de R$ 120/t", "R$ 120 por tonelada", "frete: 120"
  if ((m = low.match(new RegExp(`frete\\s*(?:de|:|=|a)?\\s*(?:r\\$)?\\s*${NUM}`)))) achados.frete_ton = m[1];
  else if ((m = low.match(new RegExp(`r\\$\\s*${NUM}\\s*(?:\\/\\s*t|por\\s+t|\\/\\s*ton|por\\s+ton)`)))) achados.frete_ton = m[1];

  // saldo em toneladas: "saldo de 1.500 t", "1500 toneladas" (não precedido de R$)
  if ((m = low.match(new RegExp(`saldo\\s*(?:de|:|=)?\\s*${NUM}`)))) achados.saldo_ton = m[1];
  else if ((m = low.match(new RegExp(`(?<!r\\$\\s?)${NUM}\\s*(?:t|ton|toneladas)\\b(?!\\s*\\/)`)))) achados.saldo_ton = m[1];

  // balança
  if (/balanca[^.\n]{0,20}sem\s+restric|sem\s+restricao/.test(low)) achados.balanca = 'sem_restricao';
  else if ((m = low.match(/balanca\s*(?:de|:|=)?\s*(20|25|30)\s*m/)) || (m = low.match(/\b(20|25|30)\s*m(?:etros)?\s*(?:de\s+)?balanca/))) achados.balanca = `${m[1]}m`;

  // antecedência: "72 horas de antecedência", "antecedência: 48h", "3 dias de antecedência"
  if ((m = low.match(new RegExp(`antecedencia\\s*(?:de|:|=)?\\s*${NUM}\\s*(h|horas?|dias?)?`)))) achados.antecedencia_h = m[2] && m[2].startsWith('dia') ? String(Number(m[1].replace(',', '.')) * 24) : m[1];
  else if ((m = low.match(new RegExp(`${NUM}\\s*(h|horas?|dias?)\\s*(?:de\\s+)?antecedencia`)))) achados.antecedencia_h = m[2].startsWith('dia') ? String(Number(m[1].replace(',', '.')) * 24) : m[1];

  // UF de origem: "do PR", "origem PR", "saindo do Paraná", ou sigla isolada em maiúsculas
  if ((m = t.match(/\b(?:origem|uf|de|do|da|saindo\s+d[eoa]|sai\s+d[eoa])\s*:?\s*([A-Z]{2})\b/)) && UFS.includes(m[1])) achados.uf_origem = m[1];
  else {
    const est = Object.keys(ESTADOS).find((e) => low.includes(e));
    if (est) achados.uf_origem = ESTADOS[est];
    else { const sig = (t.match(/\b[A-Z]{2}\b/g) || []).find((s) => UFS.includes(s)); if (sig) achados.uf_origem = sig; }
  }

  // destino: cidade conhecida do histórico ou "para <Cidade>" / "destino: <Cidade>"
  const conhecida = CIDADES_CONHECIDAS.find((c) => new RegExp(`\\b${c.toLowerCase()}\\b`).test(low));
  if (conhecida) achados.destino = conhecida;
  else if ((m = t.match(/\b(?:destino|para|ate)\s*:?\s*([A-Z][a-zA-Z]+(?:\s+(?:d[aeo]s?\s+)?[A-Z][a-zA-Z]+)*)/))) {
    if (!UFS.includes(m[1])) achados.destino = m[1];
  }
  return achados;
}

return $input.all().map((item, idx) => {
  const env = item.json;
  const dados = {}; const origem = {}; const naoMapeados = {}; const conflitos = [];

  // 1) campos estruturados (formulário, CSV, linhas "Chave: valor" do PDF/e-mail)
  for (const [campoOriginal, bruto] of Object.entries(env.campos_brutos || {})) {
    const destino = PARA_CANONICO[chave(campoOriginal)];
    if (!destino || (bruto !== null && typeof bruto === 'object')) { naoMapeados[campoOriginal] = bruto; continue; }
    const valor = String(bruto ?? '').trim();
    if (valor === '') continue;                                   // vazio = ausente (não inventamos nada)
    if (dados[destino] === undefined) { dados[destino] = valor; origem[destino] = `campo "${campoOriginal}"`; }
    else if (!mesmoValor(destino, dados[destino], valor)) conflitos.push({ campo: destino, valores: [dados[destino], valor] });
  }

  // 2) dados do solicitante informados pelo canal (remetente do e-mail, perfil do Telegram, formulário)
  const s = env.solicitante || {};
  if (!dados.nome && s.nome) { dados.nome = s.nome; origem.nome = `canal ${env.canal}`; }
  if (!dados.email && s.email) { dados.email = s.email; origem.email = `canal ${env.canal}`; }
  if (!dados.telefone && s.telefone) { dados.telefone = s.telefone; origem.telefone = `canal ${env.canal}`; }
  if (!dados.tipo && env.assunto) { dados.tipo = env.assunto; origem.tipo = 'assunto'; }
  if (!dados.observacao && env.texto) { dados.observacao = env.texto; origem.observacao = 'texto da mensagem'; }

  // 3) texto livre: extrai campos logísticos que ainda não vieram estruturados
  const textoLivre = [env.assunto, env.texto].filter(Boolean).join('\n');
  const extraidos = textoLivre ? extrairDoTexto(textoLivre) : {};
  for (const [campo, valor] of Object.entries(extraidos)) {
    if (dados[campo] === undefined) { dados[campo] = valor; origem[campo] = 'extraído do texto'; }
  }

  return { json: {
    ...env,
    dados,
    origem_dos_campos: origem,
    campos_logisticos_encontrados: CAMPOS_LOGISTICOS.filter((c) => dados[c] !== undefined),
    campos_nao_mapeados: naoMapeados,
    conflitos,
    eventos: [...env.eventos, { etapa: 'mapeamento', detalhe: `${Object.keys(dados).length} campos reconhecidos; ${Object.keys(extraidos).length} extraídos do texto livre` }],
  }, pairedItem: { item: idx } };
});

// =====================================================================
// BLOCO 3 | IDENTIFICAR TIPO DE DEMANDA  (geral x logística)
// O HUB é multissetorial: só vai para o caminho logístico (e para a IA) o que for,
// de fato, um pedido de transporte/frete. Regras, em ordem:
//   1. Tipo informado explicitamente (formulário web, Telegram, CSV) -> respeitado.
//   2. 2 ou mais atributos logísticos encontrados (produto, distância, saldo...) -> logística.
//   3. Intenção de transporte no texto ("transportar", "carregar", "preciso de frete")
//      SEM palavras fortes de outro setor (boleto, fatura, reclamação...) -> logística.
//   4. Caso contrário -> demanda geral (vai para a classificação por setor).
// =====================================================================

const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const INTENCAO_TRANSPORTE = /(transport|carregar|carregamento|preciso de (um )?(frete|caminhao|carreta)|solicit\w* (de )?frete|frete (de|para) |escoar|embarcar|carga de )/;
const OUTRO_SETOR = /(boleto|fatura|cobranca|segunda via|pagamento|reclam|cadastro|contrato|nota fiscal|curriculo|vaga|manutencao)/;

function tipoInformado(v) {
  const t = semAcento(v);
  if (['logistica', 'frete', 'transporte', 'logistico'].includes(t)) return 'logistica';
  if (['geral', 'outro', 'outros', 'administrativo'].includes(t)) return 'geral';
  return null;
}

return $input.all().map((item, idx) => {
  const j = item.json;
  const txt = semAcento([j.dados.tipo, j.dados.observacao].filter(Boolean).join(' '));
  const nLog = j.campos_logisticos_encontrados.filter((c) => c !== 'destino').length;

  let tipo; let motivo;
  const informado = tipoInformado(j.tipo_informado) || tipoInformado(j.dados.tipo_demanda);
  if (informado) { tipo = informado; motivo = 'tipo informado pelo solicitante/canal'; }
  else if (nLog >= 2) { tipo = 'logistica'; motivo = `${nLog} atributos logísticos encontrados (${j.campos_logisticos_encontrados.join(', ')})`; }
  else if (INTENCAO_TRANSPORTE.test(txt) && !OUTRO_SETOR.test(txt)) { tipo = 'logistica'; motivo = 'intenção de transporte identificada no texto'; }
  else { tipo = 'geral'; motivo = nLog ? 'poucos atributos logísticos e sem intenção clara de transporte' : 'nenhum atributo logístico encontrado'; }

  return { json: {
    ...j,
    tipo_demanda: tipo,
    motivo_tipo: motivo,
    eventos: [...j.eventos, { etapa: 'identificacao', detalhe: `Demanda ${tipo === 'logistica' ? 'LOGÍSTICA' : 'GERAL'}: ${motivo}` }],
  }, pairedItem: { item: idx } };
});

// =====================================================================
// BLOCO 4 | AUDITAR E VALIDAR  (evolução do node "Auditar e Validar" da 1ª etapa)
// Define, com critérios explícitos, a situação de cada solicitação:
//   "valida"    -> segue para o caminho GERAL ou LOGÍSTICO
//   "pendente"  -> faltam informações (o solicitante é avisado do que falta)
//   "rejeitada" -> valor inválido/inconsistente, conflito ou duplicidade no lote
// Cada problema vira um item em "motivos" (nada é descartado em silêncio).
// Regras gerais (1ª etapa): contato, e-mail, telefone, documento, data.
// Regras logísticas: 9 atributos do dataset, com tipos e faixas plausíveis.
// =====================================================================

const LOGISTICOS = {
  produto: 'Produto', uf_origem: 'UF de origem', destino: 'Destino', distancia_km: 'Distância (km)',
  frete_ton: 'Frete por tonelada (R$)', saldo_ton: 'Saldo (toneladas)', balanca: 'Tipo de balança',
  estrada_chao_km: 'Estrada de chão (km)', antecedencia_h: 'Antecedência (horas)',
};
const UFS = ['AC', 'AL', 'AP', 'AM', 'BA', 'CE', 'DF', 'ES', 'GO', 'MA', 'MT', 'MS', 'MG', 'PA', 'PB', 'PR', 'PE', 'PI', 'RJ', 'RN', 'RS', 'RO', 'RR', 'SC', 'SP', 'SE', 'TO'];
// Faixas de plausibilidade (validação de dados, não regra de negócio da IA)
const FAIXAS = {
  distancia_km: [1, 3500], frete_ton: [1, 1000], saldo_ton: [1, 100000],
  estrada_chao_km: [0, 500], antecedencia_h: [0, 720],
};
// Canais em que o solicitante pode completar a informação (os demais rejeitam o que falta)
const CANAIS_INTERATIVOS = ['web', 'telegram', 'email', 'teste'];

const digitos = (s) => String(s ?? '').replace(/\D/g, '');
const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const emailValido = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);

// Telefone brasileiro -> DDD+número (10 ou 11 dígitos) ou null. Remove +55 quando presente.
function parseTelefone(valor) {
  let d = digitos(valor);
  if ((d.length === 12 || d.length === 13) && d.startsWith('55')) d = d.slice(2);
  if (d.length === 10 && /^[1-9]{2}[2-9]/.test(d)) return d;
  if (d.length === 11 && /^[1-9]{2}9/.test(d)) return d;
  return null;
}
// Data -> AAAA-MM-DD ou null (aceita AAAA-MM-DD e DD/MM/AAAA)
function parseData(valor) {
  const s = String(valor ?? '').trim(); let a; let mes; let dia; let m;
  if ((m = s.match(/^(\d{4})-(\d{2})-(\d{2})(?:[T ].*)?$/))) { a = +m[1]; mes = +m[2]; dia = +m[3]; }
  else if ((m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/))) { dia = +m[1]; mes = +m[2]; a = +m[3]; }
  else return null;
  const dt = new Date(Date.UTC(a, mes - 1, dia));
  if (dt.getUTCFullYear() !== a || dt.getUTCMonth() !== mes - 1 || dt.getUTCDate() !== dia) return null;
  return `${a}-${String(mes).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
}
// Número em formato brasileiro ou internacional ("1.500", "1500,5", "1500.5") -> Number ou NaN
function lerNumero(v) {
  if (v === null || v === undefined || v === '') return NaN;
  if (typeof v === 'number') return v;
  // aceita unidades comuns digitadas junto do número: "450 km", "R$ 120/t", "72h", "1.500 toneladas"
  let t = String(v).trim().toLowerCase().replace(/\s/g, '').replace(/^r\$/, '')
    .replace(/(por(tonelada|ton|t)|\/(tonelada|ton|t)|km|quilometros|horas?|hrs?|h|toneladas?|ton|t|reais)$/, '');
  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(t)) t = t.replace(/\./g, '').replace(',', '.');
  else t = t.replace(',', '.');
  return /^-?\d+(\.\d+)?$/.test(t) ? Number(t) : NaN;
}
// Balança -> "20m" | "25m" | "30m" | "sem_restricao" | null
function lerBalanca(v) {
  const t = semAcento(v).replace(/\s/g, '');
  if (/^(sem_?restricao|semrestricao|livre|nenhuma)$/.test(t)) return 'sem_restricao';
  const m = t.match(/^(20|25|30)(m|metros)?$/);
  return m ? `${m[1]}m` : null;
}

function fnv(txt, seed) { let h = seed; for (const ch of txt) { h ^= ch.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }
const hash = (txt) => fnv(txt, 0x811c9dc5) + fnv(txt, 0x9747b28c);

const vistos = new Map();   // conteúdo já visto NESTE lote -> evita duplicidade (ex.: linhas repetidas no CSV)

return $input.all().map((item, idx) => {
  const j = item.json; const d = j.dados || {};
  const motivos = []; const faltando = [];
  const add = (codigo, campo, descricao) => motivos.push({ codigo, campo, descricao });
  const interativo = CANAIS_INTERATIVOS.includes(j.canal);

  // ---------- regras gerais (contato e formatos) ----------
  if (j.canal === 'web' && !d.nome) { add('AUSENTE', 'nome', 'Nome do solicitante não informado'); faltando.push('nome'); }
  if (j.canal === 'web' && !d.telefone && !d.email) { add('AUSENTE', 'contato', 'Informe telefone ou e-mail para retorno'); faltando.push('contato'); }
  if (d.telefone && !parseTelefone(d.telefone)) add('INCONSISTENTE', 'telefone', `Telefone fora do padrão brasileiro: "${d.telefone}"`);
  if (d.email && !emailValido(d.email)) add('INCONSISTENTE', 'email', `E-mail inválido: "${d.email}"`);
  if (d.data_pedido && !parseData(d.data_pedido)) add('INCONSISTENTE', 'data_pedido', `Data inválida ou ambígua: "${d.data_pedido}"`);
  if (d.documento && ![11, 14].includes(digitos(d.documento).length)) add('INCONSISTENTE', 'documento', `CPF/CNPJ com quantidade de dígitos inválida: "${d.documento}"`);
  for (const c of j.conflitos || []) add('CONFLITO', c.campo, `Campos equivalentes com valores diferentes: ${c.valores.map((v) => `"${v}"`).join(' x ')}`);

  // ---------- regras por tipo ----------
  const logistica = {};
  if (j.tipo_demanda === 'geral') {
    if (!d.tipo && !d.observacao) { add('AUSENTE', 'descricao', 'Descreva a solicitação'); faltando.push('descricao'); }
  } else {
    for (const [campo, rotulo] of Object.entries(LOGISTICOS)) {
      if (d[campo] === undefined || String(d[campo]).trim() === '') { add('AUSENTE', campo, `${rotulo} não informado(a)`); faltando.push(campo); }
    }
    if (d.produto !== undefined) logistica.produto = semAcento(d.produto).toUpperCase();
    if (d.uf_origem !== undefined) {
      const ESTADOS = { 'PARANA': 'PR', 'MATO GROSSO DO SUL': 'MS', 'MATO GROSSO': 'MT', 'SANTA CATARINA': 'SC', 'SAO PAULO': 'SP', 'RIO GRANDE DO SUL': 'RS', 'GOIAS': 'GO' };
      const bruto = semAcento(d.uf_origem).toUpperCase();
      const uf = ESTADOS[bruto] || bruto;
      if (UFS.includes(uf)) logistica.uf_origem = uf; else add('INVALIDO', 'uf_origem', `UF inválida: "${d.uf_origem}" (use a sigla, ex.: PR)`);
    }
    if (d.destino !== undefined) {
      const dest = String(d.destino).trim();
      if (dest.length >= 2 && !/^\d+$/.test(dest)) logistica.destino = dest; else add('INVALIDO', 'destino', `Destino inválido: "${d.destino}"`);
    }
    for (const campo of Object.keys(FAIXAS)) {
      if (d[campo] === undefined) continue;
      const n = lerNumero(d[campo]); const [min, max] = FAIXAS[campo];
      if (Number.isNaN(n) || n < min || n > max) add('INVALIDO', campo, `${LOGISTICOS[campo]} deve ser um número entre ${min} e ${max}: "${d[campo]}"`);
      else logistica[campo] = n;
    }
    if (d.balanca !== undefined) {
      const b = lerBalanca(d.balanca);
      if (b) logistica.balanca = b; else add('INVALIDO', 'balanca', `Balança inválida: "${d.balanca}" (use 20m, 25m, 30m ou sem_restricao)`);
    }
    if (logistica.estrada_chao_km !== undefined && logistica.distancia_km !== undefined && logistica.estrada_chao_km > logistica.distancia_km) {
      add('INCONSISTENTE', 'estrada_chao_km', 'Estrada de chão maior que a distância total');
    }
    if (d.atendida !== undefined) add('IGNORADO', 'atendida', 'Campo "atendida" recebido em demanda nova: ignorado (é o que a IA prevê)');
  }

  // ---------- duplicidade dentro do mesmo lote ----------
  const base = [j.canal, j.arquivo_id || '', semAcento(d.nome), digitos(d.telefone) || semAcento(d.email),
    semAcento(`${d.tipo || ''} ${d.observacao || ''}`), JSON.stringify(logistica)].join('|');
  const chaveConteudo = hash(base);
  const ocorrencia = (vistos.get(chaveConteudo) || 0) + 1;
  vistos.set(chaveConteudo, ocorrencia);
  if (ocorrencia > 1 && j.canal === 'csv') add('DUPLICADO', 'registro', `Mesmo conteúdo já recebido neste arquivo (ocorrência ${ocorrencia})`);

  // ---------- situação final ----------
  const bloqueantes = motivos.filter((m) => m.codigo !== 'IGNORADO');
  const soFaltam = bloqueantes.length > 0 && bloqueantes.every((m) => m.codigo === 'AUSENTE');
  // No Telegram a conversa continua: dado ausente OU inválido é perguntado de novo (não rejeita)
  const corrigivelNoChat = j.canal === 'telegram' && bloqueantes.every((m) => ['AUSENTE', 'INVALIDO', 'INCONSISTENTE'].includes(m.codigo));
  const status = bloqueantes.length === 0 ? 'valida' : ((soFaltam && interativo) || corrigivelNoChat ? 'pendente' : 'rejeitada');

  return { json: {
    ...j,
    status_validacao: status,
    motivos,
    campos_faltando: faltando,
    logistica_validada: j.tipo_demanda === 'logistica' ? logistica : null,
    eventos: [...j.eventos, { etapa: 'validacao', detalhe: status === 'valida' ? 'Validação aprovada' : `${status}: ${bloqueantes.map((m) => m.descricao).join('; ')}` }],
  }, pairedItem: { item: idx } };
});

// =====================================================================
// BLOCO 6A | NORMALIZAR DEMANDA GERAL  (node "Normalizar Dados" da 1ª etapa)
// Padroniza valores de forma conservadora (só altera quando há segurança).
// Campo ausente continua null: nada é inventado.
// =====================================================================

const PARTICULAS = new Set(['da', 'de', 'do', 'das', 'dos', 'e']);
const limpar = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

// Só ajusta a caixa se o nome veio TODO em maiúsculas ou TODO em minúsculas.
function normalizarNome(nome) {
  const n = limpar(nome);
  if (n !== n.toUpperCase() && n !== n.toLowerCase()) return n;
  return n.toLowerCase().split(' ')
    .map((p, i) => (i > 0 && PARTICULAS.has(p) ? p : p.charAt(0).toUpperCase() + p.slice(1))).join(' ');
}
function normalizarTelefone(v) {
  let d = String(v).replace(/\D/g, '');
  if ((d.length === 12 || d.length === 13) && d.startsWith('55')) d = d.slice(2);
  return d;
}
function normalizarData(v) {
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/);
  return m ? `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}` : null;
}
const emBranco = (v) => (v === undefined || v === null || v === '' ? null : v);

return $input.all().map((item, idx) => {
  const j = item.json; const d = j.dados || {};
  const normalizados = {
    nome: emBranco(d.nome && normalizarNome(d.nome)),
    telefone: emBranco(d.telefone && normalizarTelefone(d.telefone)),
    email: emBranco(d.email && limpar(d.email).toLowerCase()),
    documento: emBranco(d.documento && d.documento.replace(/\D/g, '')),
    data_pedido: emBranco(d.data_pedido && normalizarData(d.data_pedido)),
    tipo: emBranco(d.tipo && limpar(d.tipo)),
    observacao: emBranco(d.observacao && limpar(d.observacao)),
    nota_fiscal: emBranco(d.nota_fiscal && limpar(d.nota_fiscal)),
  };
  const alteracoes = Object.keys(normalizados)
    .filter((c) => d[c] !== undefined && d[c] !== normalizados[c])
    .map((c) => ({ campo: c, de: d[c], para: normalizados[c] }));

  return { json: {
    ...j,
    normalizados,
    alteracoes,
    eventos: [...j.eventos, { etapa: 'normalizacao', detalhe: `${alteracoes.length} campo(s) padronizado(s)` }],
  }, pairedItem: { item: idx } };
});

// =====================================================================
// BLOCO 6A | CLASSIFICAR SETOR POR REGRAS  (node "Classificar por Regras" da 1ª etapa)
// Classificação por PALAVRAS-CHAVE — NÃO é IA. Procura os termos no assunto + descrição
// (sem acento, sem diferenciar maiúsculas) e escolhe a regra com mais termos encontrados.
// Empate: vale a ordem da lista. Nenhum termo: "Não identificada" -> setor "Atendimento"
// (triagem humana).
//
// CONFIGURAÇÃO: para mudar setores ou palavras, edite apenas a lista REGRAS abaixo.
// Os setores são uma proposta para demonstração, não a estrutura oficial da Rodomax.
// =====================================================================

const REGRAS = [
  { categoria: 'Cobrança e pagamentos',    setor: 'Financeiro',     termos: ['boleto', 'fatura', 'segunda via', 'pagamento', 'cobranca', 'vencimento', 'reembolso', 'nota fiscal', 'pix'] },
  { categoria: 'Cotação e proposta',       setor: 'Comercial',      termos: ['cotacao', 'orcamento', 'proposta', 'tabela de preco', 'parceria', 'contratar'] },
  { categoria: 'Atraso ou rastreamento',   setor: 'Logística',      termos: ['atras', 'onde esta', 'rastre', 'previsao de entrega', 'nao chegou', 'demora', 'entrega'] },
  { categoria: 'Avaria ou extravio',       setor: 'Operacional',    termos: ['avaria', 'danific', 'extravi', 'sinistro', 'ocorrencia', 'quebrad'] },
  { categoria: 'Coleta e agendamento',     setor: 'Operacional',    termos: ['coleta', 'agendar', 'agendamento', 'retirada', 'janela'] },
  { categoria: 'Manutenção de frota',      setor: 'Operacional',    termos: ['manutencao', 'pneu', 'oficina', 'revisao', 'mecanic', 'veiculo quebrado'] },
  { categoria: 'Cadastro e documentos',    setor: 'Administrativo', termos: ['cadastro', 'contrato', 'documentacao', 'documento', 'certidao', 'atualizar dados', 'rh', 'curriculo'] },
  { categoria: 'Reclamação e suporte',     setor: 'Atendimento',    termos: ['reclam', 'insatisf', 'duvida', 'atendimento', 'suporte', 'ajuda', 'informac'] },
];

const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
// o termo precisa começar numa palavra ("atras" casa com "atrasada"; "frete" não casa dentro de "refrete")
const contem = (txt, termo) => new RegExp('(^|[^a-z0-9])' + termo).test(txt);

return $input.all().map((item, idx) => {
  const j = item.json;
  const n = j.normalizados || {};
  const txt = semAcento(`${n.tipo || ''} ${n.observacao || ''}`);

  let melhor = null;
  for (const regra of REGRAS) {
    const achados = regra.termos.filter((t) => contem(txt, t));
    if (achados.length && (!melhor || achados.length > melhor.achados.length)) melhor = { regra, achados };
  }
  const categoria = melhor ? melhor.regra.categoria : 'Não identificada';
  const setor = melhor ? melhor.regra.setor : 'Atendimento';
  const regra = melhor ? `palavras-chave: ${melhor.achados.join(', ')}` : 'nenhuma palavra-chave encontrada: triagem pelo Atendimento';

  return { json: {
    ...j,
    categoria,
    setor_responsavel: setor,
    regra_classificacao: regra,
    eventos: [...j.eventos, { etapa: 'classificacao', detalhe: `Setor ${setor} (${categoria}) — ${regra}` }],
  }, pairedItem: { item: idx } };
});

// =====================================================================
// BLOCO 6B | NORMALIZAR ATRIBUTOS LOGÍSTICOS
// Deixa os atributos no MESMO formato do dataset usado no treino:
//   produto MAIÚSCULO sem acento (MILHO) | UF em sigla (PR) | destino sem acento, iniciais
//   maiúsculas (Paranagua) | balança 20m/25m/30m/sem_restricao | números como Number.
// Dados pessoais (nome, e-mail, telefone) NÃO entram nos atributos da IA.
// =====================================================================

const semAcento = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const titulo = (s) => semAcento(s).toLowerCase().replace(/\s+/g, ' ').trim()
  .split(' ').map((p) => (['de', 'da', 'do', 'das', 'dos'].includes(p) ? p : p.charAt(0).toUpperCase() + p.slice(1))).join(' ');
const limpar = (s) => (s === undefined || s === null || String(s).trim() === '' ? null : String(s).replace(/\s+/g, ' ').trim());

return $input.all().map((item, idx) => {
  const j = item.json; const l = j.logistica_validada || {}; const d = j.dados || {};
  const atributos = {
    produto: semAcento(l.produto).toUpperCase().trim(),
    uf_origem: l.uf_origem,
    destino: titulo(l.destino),
    distancia_km: l.distancia_km,
    frete_ton: l.frete_ton,
    saldo_ton: l.saldo_ton,
    balanca: l.balanca,
    estrada_chao_km: l.estrada_chao_km,
    antecedencia_h: l.antecedencia_h,
  };
  const normalizados = {
    nome: limpar(d.nome), email: d.email ? String(d.email).trim().toLowerCase() : null,
    telefone: d.telefone ? String(d.telefone).replace(/\D/g, '') : null,
    tipo: limpar(d.tipo), observacao: limpar(d.observacao),
  };
  return { json: {
    ...j,
    atributos_ia: atributos,
    normalizados,
    eventos: [...j.eventos, { etapa: 'normalizacao', detalhe: 'Atributos logísticos padronizados no formato do dataset' }],
  }, pairedItem: { item: idx } };
});

// =====================================================================================
// BLOCO 6B | PREVER ATENDIMENTO (ÁRVORE CART TREINADA)
// Usa o modelo ATIVO salvo no PostgreSQL (tabela ia_modelos), carregado pelo node anterior.
// Para cada demanda logística:
//   1. calcula o atributo derivado frete_por_km (mesma fórmula do treino);
//   2. percorre a árvore pergunta a pergunta até uma folha (caminho de decisão);
//   3. devolve a classe da folha (sim/nao), a frequência suavizada da folha e a explicação.
// A previsão é EXPERIMENTAL: apoio à decisão, não garantia de contratação/atendimento.
// Sem modelo treinado -> a demanda é registrada com status "erro" (falha técnica da IA).
// =====================================================================================

const modelo = $input.first().json;                                  // linha de ia_modelos (ou vazio)
const demandas = $('Normalizar Atributos Logísticos').all();
const AVISO = 'Previsão experimental gerada por árvore de decisão treinada com o histórico de 500 demandas. Não é garantia de contratação nem de execução do frete; a decisão final é da equipe de operação.';

const ROTULO = {
  produto: 'Produto', uf_origem: 'UF de origem', destino: 'Destino', balanca: 'Balança', distancia_km: 'Distância (km)',
  frete_ton: 'Frete (R$/t)', saldo_ton: 'Saldo (t)', estrada_chao_km: 'Estrada de chão (km)', antecedencia_h: 'Antecedência (h)',
  frete_por_km: 'Frete por t·km (R$)',
};
const fmtNum = (v) => (typeof v === 'number' ? (Math.round(v * 10000) / 10000).toString().replace('.', ',') : String(v));
const testar = (r, no) => (no.op === '<=' ? r[no.atributo] <= no.valor : no.valor.includes(r[no.atributo]));

function percorrer(arvore, r) {
  const caminho = []; let no = arvore;
  while (no.tipo === 'divisao') {
    const ok = testar(r, no);
    const pergunta = no.op === '<=' ? `${ROTULO[no.atributo] || no.atributo} ≤ ${fmtNum(no.valor)}?` : `${ROTULO[no.atributo] || no.atributo} ∈ {${no.valor.join(', ')}}?`;
    caminho.push({ atributo: no.atributo, pergunta, valor_da_demanda: r[no.atributo], resposta: ok ? 'sim' : 'não' });
    no = ok ? no.esquerda : no.direita;
  }
  return { folha: no, caminho };
}

return demandas.map((item, idx) => {
  const j = item.json;
  if (!modelo || !modelo.arvore) {
    return { json: { ...j, previsao: null, erro_ia: 'Nenhum modelo de IA treinado. Treine o modelo na Central de Controle (Modelo de IA).',
      eventos: [...j.eventos, { etapa: 'ia', detalhe: 'Falha: nenhum modelo ativo no banco' }] }, pairedItem: { item: 0 } };
  }
  try {
    const r = { ...j.atributos_ia };
    r.frete_por_km = Math.round((r.frete_ton / r.distancia_km) * 10000) / 10000;   // igual ao IA 1

    const { folha, caminho } = percorrer(modelo.arvore, r);
    const probSim = Math.round(((folha.contagem.sim + 1) / (folha.n + 2)) * 1000) / 1000;   // suavização de Laplace
    const classe = folha.classe;
    const decisivos = [...new Set(caminho.map((c) => c.atributo))];

    // avisos de extrapolação (valores fora do que o modelo viu no treino)
    const avisos = [];
    const prep = modelo.preparacao || {};
    for (const [campo, f] of Object.entries(prep.faixas || {})) {
      if (r[campo] !== undefined && (r[campo] < f.min || r[campo] > f.max)) avisos.push(`${ROTULO[campo] || campo} = ${fmtNum(r[campo])} está fora da faixa do treino (${fmtNum(f.min)} a ${fmtNum(f.max)}): previsão por extrapolação.`);
    }
    for (const [campo, valores] of Object.entries(prep.dominios || {})) {
      if (r[campo] !== undefined && !valores.includes(r[campo])) avisos.push(`${ROTULO[campo] || campo} "${r[campo]}" não aparece no histórico de treino.`);
    }

    const texto = classe === 'sim'
      ? `Perfil semelhante ao de demandas ATENDIDAS no histórico: ${folha.contagem.sim} de ${folha.n} demandas de treino com essas características foram atendidas.`
      : `Perfil semelhante ao de demandas NÃO ATENDIDAS no histórico: ${folha.contagem.nao} de ${folha.n} demandas de treino com essas características não foram atendidas. Sugestão: revisar valor do frete, prazo e condições de acesso.`;

    const previsao = {
      classe,
      rotulo: classe === 'sim' ? 'Tende a ser atendida' : 'Risco de não ser atendida',
      prob_atendida: probSim,
      modelo_id: modelo.id,
      explicacao: {
        resumo: texto,
        caminho,
        atributos_decisivos: decisivos.map((a) => ({ atributo: a, rotulo: ROTULO[a] || a, valor: r[a] })),
        folha: { n: folha.n, sim: folha.contagem.sim, nao: folha.contagem.nao },
        frete_por_km: r.frete_por_km,
        avisos,
        modelo: { id: modelo.id, versao: modelo.versao, acuracia_teste: modelo.acuracia, acuracia_linha_base: modelo.acuracia_linha_base },
        aviso_uso: AVISO,
      },
    };
    return { json: { ...j, previsao, avisos_ia: avisos,
      eventos: [...j.eventos, { etapa: 'ia', detalhe: `Árvore ${modelo.versao}: ${previsao.rotulo} (frequência de atendimento na folha ${Math.round(probSim * 100)}%) via ${decisivos.join(', ')}` }] }, pairedItem: { item: 0 } };
  } catch (e) {
    return { json: { ...j, previsao: null, erro_ia: `Falha ao executar a árvore: ${e.message}`,
      eventos: [...j.eventos, { etapa: 'ia', detalhe: `Falha técnica: ${e.message}` }] }, pairedItem: { item: 0 } };
  }
});

// =====================================================================
// BLOCO 8 | PERGUNTAR PRÓXIMO DADO (Telegram)
// A demanda ainda está incompleta (ou com valor inválido): em vez de rejeitar, o bot
// guarda o que já foi informado e pergunta UM campo por vez. Nada é inventado.
// =====================================================================

const PERGUNTAS = {
  produto: 'Qual é o produto? (ex.: milho ou soja)',
  uf_origem: 'Qual a UF de origem da carga? (sigla, ex.: PR ou MS)',
  destino: 'Qual a cidade de destino? (ex.: Paranaguá)',
  distancia_km: 'Qual a distância da viagem em km? (ex.: 450)',
  frete_ton: 'Qual o valor do frete por tonelada, em R$? (ex.: 120)',
  saldo_ton: 'Qual o saldo de carga, em toneladas? (ex.: 1500)',
  balanca: 'Qual a restrição da balança? Responda 20m, 25m, 30m ou sem restrição.',
  estrada_chao_km: 'Quantos km do trajeto são em estrada de chão? (0 se for tudo asfalto)',
  antecedencia_h: 'Com quantas horas de antecedência o pedido está sendo feito? (ex.: 48)',
  descricao: 'Descreva sua solicitação em uma frase.',
};
const ORDEM = Object.keys(PERGUNTAS);

return $input.all().map((item, idx) => {
  const j = item.json;
  const anterior = (j.telegram && j.telegram.estado_anterior) || {};
  const invalidos = (j.motivos || []).filter((m) => m.codigo !== 'AUSENTE' && m.codigo !== 'IGNORADO');
  const camposInvalidos = invalidos.map((m) => m.campo).filter((c) => PERGUNTAS[c]);
  const pendentes = [...new Set([...camposInvalidos, ...(j.campos_faltando || [])])].filter((c) => PERGUNTAS[c]);
  pendentes.sort((a, b) => ORDEM.indexOf(a) - ORDEM.indexOf(b));
  const proximo = pendentes[0] || null;

  // guarda os campos já reconhecidos (exceto os inválidos, que serão perguntados de novo)
  const campos = {};
  for (const [k, v] of Object.entries(j.dados || {})) if (!camposInvalidos.includes(k) && ORDEM.includes(k)) campos[k] = v;
  const textos = (j.dados_originais && j.dados_originais.mensagens) || anterior.textos || [];

  const partes = [];
  if (!anterior.tipo && j.tipo_demanda === 'logistica') partes.push('Entendi: é um pedido de FRETE. Vou registrar e analisar a chance de atendimento.');
  if (invalidos.length) partes.push(`Não consegui aceitar: ${invalidos.map((m) => m.descricao).join('; ')}.`);
  const jaTenho = ORDEM.filter((c) => c !== 'descricao' && campos[c] !== undefined);
  if (j.tipo_demanda === 'logistica' && jaTenho.length) partes.push(`Já anotei: ${jaTenho.map((c) => `${c}=${campos[c]}`).join(', ')}.`);
  partes.push(proximo ? PERGUNTAS[proximo] : 'Pode detalhar melhor sua solicitação?');
  if (pendentes.length > 1) partes.push(`(faltam ${pendentes.length} informações — /cancelar para recomeçar)`);

  return { json: {
    chat_id: j.telegram.chat_id,
    update_id: j.telegram.update_id,
    estado: { tipo: j.tipo_demanda, campos, textos, aguardando: proximo, atualizado_em: new Date().toISOString() },
    texto: partes.join('\n'),
  }, pairedItem: { item: idx } };
});

// =====================================================================
// BLOCO 7 | MONTAR REGISTRO PARA O POSTGRESQL
// Recebe os três caminhos unidos (gerais classificadas, logísticas com previsão e
// pendentes/rejeitadas) e monta o JSON gravado pela função hub_registrar_demanda().
// Situação final:
//   processada | pendente | rejeitada | erro (falha técnica, ex.: IA sem modelo treinado)
// =====================================================================

const RESPOSTA_INICIAL = {   // como a resposta é entregue em cada canal
  web: ['enviada', 'Resposta devolvida na tela da aplicação web'],
  pdf: ['enviada', 'Resposta devolvida na tela da aplicação web'],
  telegram: ['enviada', 'Texto devolvido ao conector do Telegram para envio ao usuário'],
  email: ['pendente', 'Aguardando envio por e-mail (SMTP)'],
  csv: ['nao_aplicavel', 'Importação em lote: resultado exibido na Central de Controle'],
  teste: ['nao_aplicavel', 'Caso de teste manual'],
};

return $input.all().map((item, idx) => {
  const j = item.json;
  const s = j.solicitante || {};
  const n = j.normalizados || {};
  const d = j.dados || {};
  let status = j.status_validacao === 'valida' ? 'processada' : j.status_validacao;
  if (j.tipo_demanda === 'logistica' && status === 'processada' && !j.previsao) status = 'erro';
  const motivos = [...(j.motivos || [])];
  if (j.erro_ia) motivos.push({ codigo: 'ERRO_IA', campo: 'ia', descricao: j.erro_ia });
  const [respStatus, respDetalhe] = RESPOSTA_INICIAL[j.canal] || ['pendente', null];

  const registro = {
    chave_evento: j.chave_evento,
    canal: j.canal,
    tipo_demanda: j.tipo_demanda,
    status,
    solicitante_nome: n.nome || d.nome || s.nome || null,
    solicitante_email: n.email || d.email || s.email || null,
    solicitante_telefone: n.telefone || d.telefone || s.telefone || null,
    telegram_chat_id: s.telegram_chat_id || null,
    assunto: n.tipo || d.tipo || j.assunto || null,
    descricao: n.observacao || d.observacao || j.texto || null,
    categoria: j.categoria || null,
    setor_responsavel: j.setor_responsavel || (j.tipo_demanda === 'logistica' ? 'Logística' : null),
    regra_classificacao: j.regra_classificacao || (j.tipo_demanda === 'logistica' ? `caminho logístico: ${j.motivo_tipo}` : null),
    motivos,
    avisos: j.avisos_ia || [],
    dados_originais: j.dados_originais,
    dados_normalizados: { campos: d, origem_dos_campos: j.origem_dos_campos, normalizados: n, alteracoes: j.alteracoes || [], campos_nao_mapeados: Object.keys(j.campos_nao_mapeados || {}) },
    arquivo_id: j.arquivo_id || null,
    linha_arquivo: j.linha_arquivo || null,
    resposta_status: respStatus,
    resposta_detalhe: respDetalhe,
    ambiente: j.ambiente,
    recebido_em: j.recebido_em,
    logistica: j.tipo_demanda === 'logistica' ? (j.atributos_ia || j.logistica_validada || {}) : null,
    previsao: j.previsao || null,
    eventos: [...(j.eventos || []), { etapa: 'registro', detalhe: `Situação final: ${status}` }],
  };
  return { json: { registro, contexto: { canal: j.canal, resposta: j.resposta || {}, tipo_demanda: j.tipo_demanda, status, campos_faltando: j.campos_faltando || [], motivos, previsao: j.previsao || null, setor: registro.setor_responsavel, categoria: registro.categoria, solicitante: registro.solicitante_nome, arquivo_id: j.arquivo_id || null, linha_arquivo: j.linha_arquivo || null, telegram: j.telegram || null } }, pairedItem: { item: idx } };
});

// =====================================================================
// BLOCO 8 | MONTAR RESPOSTA (mesmo conteúdo para todos os canais)
// O canal de origem só muda COMO a resposta é entregue (tela web, Telegram, e-mail).
//   Demanda geral     -> protocolo + setor responsável (SEM previsão logística)
//   Demanda logística -> protocolo + previsão da árvore + aviso de caráter experimental
//   Pendente/rejeitada-> protocolo + o que falta/corrigir
//   Falha no banco    -> erro técnico (nenhum protocolo é inventado)
// =====================================================================

const registros = $('Montar Registro').all();
const pct = (x) => `${Math.round(Number(x) * 100)}%`;
const descreverErro = (e) => (!e ? 'falha no banco de dados' : typeof e === 'string' ? e
  : String(e.message || e.description || JSON.stringify(e)).slice(0, 300));

return $input.all().map((item, i) => {
  const ctx = registros[i].json.contexto;
  const reg = registros[i].json.registro;
  const r = item.json.r || item.json.resultado || null;          // retorno de hub_registrar_demanda()
  const falhaBanco = !r || !r.protocolo;

  const linhas = [];
  let titulo; let situacao = ctx.status;
  if (falhaBanco) {
    situacao = 'erro_tecnico';
    titulo = 'Não foi possível registrar sua solicitação agora';
    linhas.push('Ocorreu uma falha técnica ao gravar no banco de dados. Nenhum protocolo foi gerado. Tente novamente em instantes.');
  } else if (ctx.status === 'pendente') {
    titulo = 'Solicitação recebida — faltam informações';
    linhas.push(`Protocolo: ${r.protocolo}`, 'Para continuar, precisamos de:', ...ctx.motivos.filter((m) => m.codigo !== 'IGNORADO').map((m) => `• ${m.descricao}`));
  } else if (ctx.status === 'rejeitada') {
    titulo = 'Solicitação recebida, mas com dados inválidos';
    linhas.push(`Protocolo: ${r.protocolo}`, 'Corrija e envie novamente:', ...ctx.motivos.filter((m) => m.codigo !== 'IGNORADO').map((m) => `• ${m.descricao}`));
  } else if (ctx.status === 'erro') {
    titulo = 'Solicitação registrada — análise da IA indisponível';
    linhas.push(`Protocolo: ${r.protocolo}`, 'Sua demanda logística foi registrada, mas a previsão não pôde ser gerada agora. A equipe de Logística fará a análise.');
  } else if (ctx.tipo_demanda === 'geral') {
    titulo = 'Solicitação recebida e encaminhada';
    linhas.push(`Protocolo: ${r.protocolo}`, `Encaminhada ao setor: ${ctx.setor}`, `Assunto identificado: ${ctx.categoria}`, 'O setor responsável dará continuidade ao atendimento.');
  } else {
    const p = ctx.previsao;
    titulo = 'Demanda de frete recebida e analisada';
    linhas.push(
      `Protocolo: ${r.protocolo}`,
      `Previsão da IA: ${p.rotulo.toUpperCase()}`,
      `Frequência de atendimento em casos semelhantes do histórico: ${pct(p.prob_atendida)} (${p.explicacao.folha.sim} de ${p.explicacao.folha.n})`,
      `Principais fatores: ${p.explicacao.atributos_decisivos.map((a) => a.rotulo).join(', ')}`,
      p.explicacao.resumo,
      '',
      'Importante: esta é uma previsão EXPERIMENTAL. A demanda foi registrada e analisada — o frete ainda NÃO está contratado. A decisão final é da equipe de operação.',
    );
  }
  if (r && r.duplicado) linhas.push('', '(Este envio já havia sido recebido; mantivemos o registro original.)');
  const textoFinal = [titulo, '', ...linhas].join('\n');

  return { json: {
    canal: ctx.canal,
    demanda_id: r ? r.id : null,
    protocolo: r ? r.protocolo : null,
    duplicado: !!(r && r.duplicado),
    situacao,
    tipo_demanda: ctx.tipo_demanda,
    titulo,
    texto: textoFinal,
    // dados para a tela web
    resultado: {
      ok: !falhaBanco, protocolo: r ? r.protocolo : null, situacao, tipo_demanda: ctx.tipo_demanda,
      setor: ctx.tipo_demanda === 'geral' ? ctx.setor : null, categoria: ctx.categoria,
      previsao: ctx.tipo_demanda === 'logistica' ? ctx.previsao : null,
      motivos: ctx.motivos, titulo, mensagem: linhas.join('\n'), duplicado: !!(r && r.duplicado),
      erro_tecnico: falhaBanco ? descreverErro(item.json.error) : null,
    },
    // entrega por canal
    email_destino: ctx.resposta.email || null,
    email_assunto: ctx.resposta.assunto || 'Rodomax HUB — sua solicitação',
    chat_id: ctx.resposta.chat_id || null,
    update_id: ctx.resposta.update_id || null,
    arquivo_id: ctx.arquivo_id,
    linha_arquivo: ctx.linha_arquivo,
    previsao_classe: ctx.previsao ? ctx.previsao.classe : null,
    descricao_curta: (reg.descricao || '').slice(0, 80),
  }, pairedItem: { item: i } };
});

// =====================================================================
// BLOCO 10 | VERIFICAR ENVIO DO E-MAIL
// O node "Enviar Resposta por E-mail" continua mesmo se falhar (On Error: continuar).
// Aqui descobrimos o que aconteceu e registramos — a demanda NUNCA é apagada:
//   accepted preenchido -> "enviada"
//   error               -> "nao_enviada" (motivo registrado)
//   node desativado     -> "nao_enviada" (envio por e-mail ainda não configurado)
// =====================================================================

const originais = $('Responder por Canal').all(2);   // saída 2 do Switch = e-mail
return $input.all().map((item, i) => {
  const r = item.json || {};
  const o = (originais[i] || item).json;
  let status; let detalhe;
  if (Array.isArray(r.accepted) && r.accepted.length) { status = 'enviada'; detalhe = `SMTP aceitou para ${r.accepted.join(', ')}`; }
  else if (r.error) { status = 'nao_enviada'; detalhe = `Falha no envio: ${String(r.error.message || r.error).slice(0, 300)}`; }
  else { status = 'nao_enviada'; detalhe = 'Envio por e-mail desativado no workflow (configure a credencial SMTP e ative o node).'; }
  return { json: { demanda_id: o.demanda_id, protocolo: o.protocolo, status, detalhe }, pairedItem: { item: i } };
});

// =====================================================================
// BLOCO 8 | RESUMO DO LOTE CSV
// Um CSV é UM arquivo com N registros. A resposta informa, para o arquivo:
// lidos, processados, pendentes, rejeitados, com erro e as previsões da IA.
// Contadores oficiais vêm do banco (hub_atualizar_arquivo); detalhes, desta execução.
// =====================================================================

const lote = $input.first().json.lote || {};
const itens = $('Montar Resposta').all().map((i) => i.json).filter((j) => j.canal === 'csv');
const contar = (f) => itens.filter(f).length;

return [{ json: {
  ok: true,
  arquivo_id: lote.arquivo_id,
  nome_arquivo: lote.nome_arquivo,
  finalidade: 'novas_demandas',
  registros_lidos: lote.registros_total,
  registros_importados: lote.registros_importados,
  registros_rejeitados: lote.registros_rejeitados,
  nesta_execucao: {
    processadas: contar((j) => j.situacao === 'processada'),
    pendentes: contar((j) => j.situacao === 'pendente'),
    rejeitadas: contar((j) => j.situacao === 'rejeitada'),
    com_erro: contar((j) => j.situacao === 'erro' || j.situacao === 'erro_tecnico'),
    duplicadas_ignoradas: contar((j) => j.duplicado),
    gerais: contar((j) => j.tipo_demanda === 'geral'),
    logisticas: contar((j) => j.tipo_demanda === 'logistica'),
    previsao_atendida: contar((j) => j.previsao_classe === 'sim'),
    previsao_nao_atendida: contar((j) => j.previsao_classe === 'nao'),
  },
  amostra: itens.slice(0, 25).map((j) => ({ linha: j.linha_arquivo, protocolo: j.protocolo, situacao: j.situacao, tipo: j.tipo_demanda, previsao: j.previsao_classe, mensagem: j.resultado.mensagem.split('\n').slice(0, 3).join(' | ') })),
} }];

// =====================================================================================
// BLOCO IA | IA 1 - PREPARAR DADOS HISTÓRICOS  (evolução do "IA 2 - Preparar e Separar")
// Base: tabela ia_historico (importada do rodomax_demandas.csv da professora). Sem dados sintéticos.
// 1) confere tipos, ausentes e valores inválidos (registros problemáticos são excluídos e CONTADOS);
// 2) analisa VAZAMENTO DE INFORMAÇÃO em status_agendamento (tabela cruzada com "atendida");
// 3) monta os atributos do modelo (+ atributo derivado frete_por_km);
// 4) separa treino (80%) e teste (20%) de forma ESTRATIFICADA, com semente fixa.
// =====================================================================================

const SEMENTE_SEPARACAO = 42;   // semente fixa => a mesma separação em toda execução
const PROPORCAO_TESTE = 0.20;   // 80% treino / 20% teste
const MINIMO_REGISTROS = 50;
const CLASSES = ['sim', 'nao'];  // valores da coluna alvo "atendida"

// Atributos de ENTRADA do modelo. Excluídos de propósito (ver IA_E_AVALIACAO.md):
//   id_demanda          -> identificador, não tem significado preditivo
//   status_agendamento  -> VAZAMENTO: o agendamento é consequência do atendimento
//   canal               -> canal de recebimento histórico (WhatsApp/planilha...); não descreve a carga
//                          e os canais atuais (Telegram/Web) não existem no histórico
//   atendida            -> é a variável ALVO
const ATRIBUTOS = [
  { nome: 'produto',         tipo: 'cat', descricao: 'Produto transportado (MILHO, SOJA)' },
  { nome: 'uf_origem',       tipo: 'cat', descricao: 'UF de origem da carga' },
  { nome: 'destino',         tipo: 'cat', descricao: 'Cidade de destino' },
  { nome: 'balanca',         tipo: 'cat', descricao: 'Restrição de balança (20m, 25m, 30m, sem_restricao)' },
  { nome: 'distancia_km',    tipo: 'num', descricao: 'Distância da viagem (km)' },
  { nome: 'frete_ton',       tipo: 'num', descricao: 'Valor do frete por tonelada (R$)' },
  { nome: 'saldo_ton',       tipo: 'num', descricao: 'Saldo de carga a transportar (t)' },
  { nome: 'estrada_chao_km', tipo: 'num', descricao: 'Trecho em estrada de chão (km)' },
  { nome: 'antecedencia_h',  tipo: 'num', descricao: 'Antecedência do pedido (horas)' },
  { nome: 'frete_por_km',    tipo: 'num', descricao: 'Derivado: frete_ton / distancia_km (R$ por t·km)' },
];
// O MESMO cálculo é repetido no node "Prever Atendimento" (precisa ser idêntico)
const derivar = (r) => ({ ...r, frete_por_km: Math.round((r.frete_ton / r.distancia_km) * 10000) / 10000 });

const linhas = ($input.first().json.registros) || [];
if (linhas.length < MINIMO_REGISTROS) {
  // não lança exceção: devolve o erro para o node "Base Suficiente?" responder de forma clara
  return [{ json: { ok: false, erro: `Base histórica com ${linhas.length} registro(s). Importe o rodomax_demandas.csv (finalidade "Base histórica") antes de treinar — mínimo ${MINIMO_REGISTROS}.` } }];
}

// ---------- 1) conferência de qualidade ----------
const NUMERICOS = ATRIBUTOS.filter((a) => a.tipo === 'num' && a.nome !== 'frete_por_km').map((a) => a.nome);
const CATEGORICOS = ATRIBUTOS.filter((a) => a.tipo === 'cat').map((a) => a.nome);
const ausentes = Object.fromEntries([...NUMERICOS, ...CATEGORICOS, 'atendida'].map((c) => [c, 0]));
const excluidos = [];
const base = [];
for (const l of linhas) {
  const r = { id_demanda: Number(l.id_demanda), status_agendamento: l.status_agendamento, canal: l.canal };
  let ok = true;
  for (const c of NUMERICOS) {
    const v = l[c] === null || l[c] === undefined || l[c] === '' ? NaN : Number(l[c]);
    if (Number.isNaN(v)) { ausentes[c]++; ok = false; } else r[c] = v;
  }
  for (const c of CATEGORICOS) {
    const v = String(l[c] ?? '').trim();
    if (!v) { ausentes[c]++; ok = false; } else r[c] = v;
  }
  r.atendida = String(l.atendida ?? '').trim().toLowerCase();
  if (!CLASSES.includes(r.atendida)) { ausentes.atendida++; ok = false; }
  if (ok && (r.distancia_km <= 0 || r.frete_ton <= 0 || r.saldo_ton <= 0 || r.estrada_chao_km < 0 || r.antecedencia_h < 0)) ok = false;
  if (ok) base.push(derivar(r)); else excluidos.push(l.id_demanda);
}
const contar = (lista) => Object.fromEntries(CLASSES.map((c) => [c, lista.filter((r) => r.atendida === c).length]));

// ---------- 2) análise de vazamento: status_agendamento x atendida ----------
const cruzada = {};
for (const r of base) {
  const s = r.status_agendamento || '(vazio)';
  cruzada[s] = cruzada[s] || { sim: 0, nao: 0 };
  cruzada[s][r.atendida]++;
}
const vazamento = Object.entries(cruzada).map(([status, c]) => ({
  status_agendamento: status, sim: c.sim, nao: c.nao,
  percentual_atendida: Math.round((1000 * c.sim) / (c.sim + c.nao)) / 10,
}));

// ---------- 3) estatísticas descritivas (para o relatório) ----------
const descritiva = {};
for (const c of [...NUMERICOS, 'frete_por_km']) {
  const v = base.map((r) => r[c]).sort((a, b) => a - b);
  const media = v.reduce((s, x) => s + x, 0) / v.length;
  descritiva[c] = { min: v[0], max: v[v.length - 1], media: Math.round(media * 100) / 100, mediana: v[Math.floor(v.length / 2)] };
}
const dominios = {};
for (const c of CATEGORICOS) dominios[c] = [...new Set(base.map((r) => r[c]))].sort();

// ---------- 4) separação estratificada treino/teste ----------
function criarGerador(semente) {   // mulberry32 (mesmo gerador da 1ª versão)
  let a = semente >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0; let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = criarGerador(SEMENTE_SEPARACAO);
function embaralhar(lista) { const v = lista.slice(); for (let i = v.length - 1; i > 0; i--) { const k = Math.floor(rnd() * (i + 1)); [v[i], v[k]] = [v[k], v[i]]; } return v; }
const ordenada = base.slice().sort((a, b) => a.id_demanda - b.id_demanda);   // independe da ordem de leitura
const treino = []; const teste = [];
for (const classe of CLASSES) {
  const grupo = embaralhar(ordenada.filter((r) => r.atendida === classe));
  const nTeste = Math.round(grupo.length * PROPORCAO_TESTE);
  teste.push(...grupo.slice(0, nTeste));
  treino.push(...grupo.slice(nTeste));
}
const faixas = {};
for (const c of [...NUMERICOS, 'frete_por_km']) faixas[c] = { min: Math.min(...treino.map((r) => r[c])), max: Math.max(...treino.map((r) => r[c])) };

return [{ json: {
  ok: true,
  atributos: ATRIBUTOS,
  classes: CLASSES,
  treino,
  teste,
  preparacao: {
    fonte: 'ia_historico (rodomax_demandas.csv)',
    registros_lidos: linhas.length,
    registros_utilizados: base.length,
    registros_excluidos: excluidos.length,
    ids_excluidos: excluidos.slice(0, 50),
    ausentes_por_campo: ausentes,
    distribuicao_classes: contar(base),
    atributos_excluidos: [
      { atributo: 'id_demanda', motivo: 'identificador sem significado preditivo' },
      { atributo: 'status_agendamento', motivo: 'vazamento de informação: reflete o resultado (ver tabela cruzada)' },
      { atributo: 'canal', motivo: 'canal histórico (WhatsApp/planilha/e-mail/webhook) não descreve a carga; canais atuais (Telegram/Web) não existem no histórico' },
    ],
    atributo_derivado: 'frete_por_km = frete_ton / distancia_km',
    vazamento_status_agendamento: vazamento,
    descritiva,
    dominios,
    faixas,
    semente_separacao: SEMENTE_SEPARACAO,
    proporcao_teste: PROPORCAO_TESTE,
    estratificada: true,
    treino: { registros: treino.length, classes: contar(treino) },
    teste: { registros: teste.length, classes: contar(teste) },
  },
} }];

// =====================================================================================
// BLOCO IA | IA 2 - TREINAR ÁRVORE DE DECISÃO (CART com índice Gini, JavaScript puro)
// (evolução do node "IA 3 - Treinar Árvore (Gini)" da versão anterior)
//
// Aprendizado supervisionado: a árvore aprende, SÓ com o conjunto de TREINO, quais perguntas
// melhor separam "atendida = sim" de "atendida = nao". Nenhuma regra é escrita à mão.
//
// Algoritmo CART (para cada nó, recursivamente):
//   1. impureza de Gini do nó:  Gini = 1 - Σ p(classe)²
//   2. testa as divisões possíveis de cada atributo:
//        numérico:   "atributo <= limiar"   (limiar = ponto médio entre valores consecutivos)
//        categórico: "atributo ∈ {grupo}"  (categorias ordenadas pela proporção de "nao";
//                     para alvo binário isso encontra a melhor partição — Breiman et al., 1984)
//   3. escolhe a divisão de maior GANHO = Gini(pai) - média ponderada dos Gini dos filhos
//   4. divide e repete; vira FOLHA ao atingir profundidade máxima, poucos registros,
//      nó puro ou nenhuma divisão com ganho.
//
// Escolha da profundidade: VALIDAÇÃO CRUZADA (5 partes) feita APENAS no treino. O conjunto
// de teste fica guardado para a avaliação final (no node seguinte).
// =====================================================================================

const PARAMETROS = {
  criterio: 'gini',
  profundidades_avaliadas: [2, 3, 4, 5, 6, 7, 8],
  min_amostras_divisao: 10,     // nó com menos registros que isso não é dividido
  min_amostras_folha: 5,        // cada folha precisa ter pelo menos isso
  ganho_minimo: 1e-6,
  folds_validacao_cruzada: 5,
  semente_folds: 7,
};

const d = $input.first().json;
const CLASSES = d.classes;               // ['sim', 'nao']
const ALVO = 'atendida';

// --------------------------- CART ---------------------------
function contarClasses(regs) { const c = { sim: 0, nao: 0 }; for (const r of regs) c[r[ALVO]]++; return c; }
function gini(c, n) { if (n === 0) return 0; let s = 0; for (const k of CLASSES) s += (c[k] / n) ** 2; return 1 - s; }
const majoritaria = (c) => (c.nao > c.sim ? 'nao' : 'sim');   // empate -> 'sim'
const testar = (r, dv) => (dv.op === '<=' ? r[dv.atributo] <= dv.valor : dv.valor.includes(r[dv.atributo]));

function melhorDivisao(regs, atributos, p) {
  const n = regs.length; const cPai = contarClasses(regs); const gPai = gini(cPai, n);
  let melhor = null;
  const avaliar = (atributo, op, valor, cEsq, nEsq) => {
    const nDir = n - nEsq;
    if (nEsq < p.min_amostras_folha || nDir < p.min_amostras_folha) return;
    const cDir = { sim: cPai.sim - cEsq.sim, nao: cPai.nao - cEsq.nao };
    const ganho = gPai - ((nEsq / n) * gini(cEsq, nEsq) + (nDir / n) * gini(cDir, nDir));
    if (ganho > p.ganho_minimo && (!melhor || ganho > melhor.ganho + 1e-12)) melhor = { atributo, op, valor, ganho };
  };
  for (const a of atributos) {
    if (a.tipo === 'num') {
      const ord = regs.slice().sort((x, y) => x[a.nome] - y[a.nome]);
      const cEsq = { sim: 0, nao: 0 };
      for (let i = 0; i < n - 1; i++) {
        cEsq[ord[i][ALVO]]++;
        const v1 = ord[i][a.nome]; const v2 = ord[i + 1][a.nome];
        if (v1 === v2) continue;
        avaliar(a.nome, '<=', Math.round(((v1 + v2) / 2) * 10000) / 10000, { ...cEsq }, i + 1);
      }
    } else {
      const porCat = {};
      for (const r of regs) { const v = r[a.nome]; porCat[v] = porCat[v] || { sim: 0, nao: 0 }; porCat[v][r[ALVO]]++; }
      const cats = Object.keys(porCat).sort((x, y) => {
        const px = porCat[x].nao / (porCat[x].sim + porCat[x].nao); const py = porCat[y].nao / (porCat[y].sim + porCat[y].nao);
        return px - py || (x < y ? -1 : 1);
      });
      const cEsq = { sim: 0, nao: 0 }; let nEsq = 0;
      for (let i = 0; i < cats.length - 1; i++) {
        cEsq.sim += porCat[cats[i]].sim; cEsq.nao += porCat[cats[i]].nao; nEsq += porCat[cats[i]].sim + porCat[cats[i]].nao;
        avaliar(a.nome, 'in', cats.slice(0, i + 1), { ...cEsq }, nEsq);
      }
    }
  }
  return melhor;
}

function construir(regs, prof, atributos, p, importancia, nTotal) {
  const n = regs.length; const c = contarClasses(regs); const g = gini(c, n);
  const folha = { tipo: 'folha', classe: majoritaria(c), n, contagem: c, gini: Math.round(g * 1000) / 1000 };
  if (prof >= p.profundidade_maxima || n < p.min_amostras_divisao || g === 0) return folha;
  const dv = melhorDivisao(regs, atributos, p);
  if (!dv) return folha;
  if (importancia) importancia[dv.atributo] += (n / nTotal) * dv.ganho;
  const esq = regs.filter((r) => testar(r, dv)); const dir = regs.filter((r) => !testar(r, dv));
  return {
    tipo: 'divisao', atributo: dv.atributo, op: dv.op, valor: dv.valor, n, contagem: c,
    gini: Math.round(g * 1000) / 1000, ganho: Math.round(dv.ganho * 10000) / 10000,
    esquerda: construir(esq, prof + 1, atributos, p, importancia, nTotal),   // condição verdadeira
    direita: construir(dir, prof + 1, atributos, p, importancia, nTotal),    // condição falsa
  };
}
function prever(no, r) { while (no.tipo === 'divisao') no = testar(r, no) ? no.esquerda : no.direita; return no.classe; }
function treinar(regs, atributos, p, importancia) { return construir(regs, 0, atributos, p, importancia, regs.length); }
const acuracia = (arv, regs) => regs.filter((r) => prever(arv, r) === r[ALVO]).length / regs.length;

// ------------------- validação cruzada (somente no treino) -------------------
function criarGerador(semente) { let a = semente >>> 0; return function () { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const rnd = criarGerador(PARAMETROS.semente_folds);
const K = PARAMETROS.folds_validacao_cruzada;
const folds = Array.from({ length: K }, () => []);
for (const classe of CLASSES) {   // folds estratificados
  const grupo = d.treino.filter((r) => r[ALVO] === classe).sort((a, b) => a.id_demanda - b.id_demanda);
  for (let i = grupo.length - 1; i > 0; i--) { const k = Math.floor(rnd() * (i + 1)); [grupo[i], grupo[k]] = [grupo[k], grupo[i]]; }
  grupo.forEach((r, i) => folds[i % K].push(r));
}
const media = (v) => v.reduce((s, x) => s + x, 0) / v.length;
const desvio = (v) => { const m = media(v); return Math.sqrt(media(v.map((x) => (x - m) ** 2))); };
const r3 = (x) => Math.round(x * 1000) / 1000;

const validacao = PARAMETROS.profundidades_avaliadas.map((prof) => {
  const p = { ...PARAMETROS, profundidade_maxima: prof };
  const accs = folds.map((_, k) => {
    const tr = folds.filter((__, i) => i !== k).flat();
    return acuracia(treinar(tr, d.atributos, p), folds[k]);
  });
  return { profundidade_maxima: prof, acuracia_media: r3(media(accs)), desvio_padrao: r3(desvio(accs)), por_fold: accs.map(r3) };
});
// melhor média; empate (diferença < 0,005) -> a árvore MAIS RASA (mais simples de explicar)
const melhorMedia = Math.max(...validacao.map((v) => v.acuracia_media));
const escolhida = validacao.find((v) => melhorMedia - v.acuracia_media < 0.005);
const PARAMS_FINAIS = { ...PARAMETROS, profundidade_maxima: escolhida.profundidade_maxima };

// ------------------- treino final com todo o conjunto de treino -------------------
const importancia = Object.fromEntries(d.atributos.map((a) => [a.nome, 0]));
const arvore = treinar(d.treino, d.atributos, PARAMS_FINAIS, importancia);

// ------------------- experimento de VAZAMENTO (somente para documentação) -------------------
// Mesma técnica, mesmos parâmetros, mas INCLUINDO status_agendamento. Se a acurácia saltar,
// confirma que o atributo "entrega a resposta" e por isso NÃO é usado no modelo oficial.
const atributosComVazamento = [...d.atributos, { nome: 'status_agendamento', tipo: 'cat' }];
const arvoreVazamento = treinar(d.treino, atributosComVazamento, PARAMS_FINAIS);
const experimentoVazamento = {
  descricao: 'Árvore treinada INCLUINDO status_agendamento (não utilizada em produção)',
  acuracia_teste: r3(acuracia(arvoreVazamento, d.teste)),
  primeira_pergunta: arvoreVazamento.tipo === 'divisao' ? `${arvoreVazamento.atributo} ${arvoreVazamento.op} ${JSON.stringify(arvoreVazamento.valor)}` : 'folha',
};

// ------------------- resumo e texto da árvore -------------------
let nNos = 0; let nFolhas = 0; let profReal = 0;
(function percorrer(no, p) { nNos++; profReal = Math.max(profReal, p); if (no.tipo === 'folha') { nFolhas++; return; } percorrer(no.esquerda, p + 1); percorrer(no.direita, p + 1); })(arvore, 0);
const fmt = (no) => (no.op === '<=' ? `${no.atributo} <= ${no.valor}` : `${no.atributo} ∈ {${no.valor.join(', ')}}`);
const linhas = [];
(function imprimir(no, recuo) {
  if (no.tipo === 'folha') { linhas.push(`${recuo}=> atendida=${no.classe}  (n=${no.n}; sim=${no.contagem.sim}, nao=${no.contagem.nao})`); return; }
  linhas.push(`${recuo}${fmt(no)}  [n=${no.n}, gini=${no.gini}, ganho=${no.ganho}]`);
  imprimir(no.esquerda, recuo + '|  sim: '); imprimir(no.direita, recuo + '|  não: ');
})(arvore, '');
const soma = Object.values(importancia).reduce((a, b) => a + b, 0) || 1;
const importancias = Object.entries(importancia)
  .map(([atributo, v]) => ({ atributo, importancia: r3(v / soma) }))
  .sort((a, b) => b.importancia - a.importancia);

return [{ json: {
  ...d,
  modelo: {
    algoritmo: 'Árvore de Decisão CART (índice Gini) — JavaScript puro no n8n',
    parametros: PARAMS_FINAIS,
    validacao_cruzada: { folds: K, resultados: validacao, profundidade_escolhida: escolhida.profundidade_maxima,
      criterio: 'maior acurácia média nos 5 folds do TREINO; empate (< 0,5 p.p.) favorece a árvore mais rasa' },
    nos: nNos, folhas: nFolhas, profundidade_real: profReal,
    importancias,
    arvore_texto: linhas.join('\n'),
    arvore,
    experimento_vazamento: experimentoVazamento,
  },
} }];

// =====================================================================================
// BLOCO IA | IA 3 - AVALIAR O MODELO E MONTAR O REGISTRO  (evolução do "IA 4 - Avaliar")
// Usa o conjunto de TESTE (20%, nunca visto no treino nem na validação cruzada).
// Todas as métricas são calculadas aqui a partir das previsões; nenhum número é digitado.
//   Classe positiva = "nao" (NÃO atendida): é o risco que a operação quer detectar.
//   Precisão = dos casos apontados como "nao", quantos realmente eram "nao".
//   Recall   = dos casos que realmente eram "nao", quantos o modelo encontrou.
//   F1       = média harmônica de precisão e recall.
//   Linha de base: prever SEMPRE a classe mais frequente do TREINO.
// =====================================================================================

const d = $input.first().json;
const POS = 'nao'; const NEG = 'sim'; const ALVO = 'atendida';
const arvore = d.modelo.arvore;
const testar = (r, no) => (no.op === '<=' ? r[no.atributo] <= no.valor : no.valor.includes(r[no.atributo]));
function folhaDe(no, r) { while (no.tipo === 'divisao') no = testar(r, no) ? no.esquerda : no.direita; return no; }
const r3 = (x) => Math.round(x * 1000) / 1000;
const div = (a, b) => (b === 0 ? 0 : a / b);   // convenção: divisão por zero => 0

function metricas(reais, previstos) {
  let vp = 0; let fp = 0; let fn = 0; let vn = 0;
  reais.forEach((real, i) => {
    const p = previstos[i];
    if (real === POS && p === POS) vp++; else if (real !== POS && p === POS) fp++;
    else if (real === POS && p !== POS) fn++; else vn++;
  });
  const precisao = div(vp, vp + fp); const recall = div(vp, vp + fn);
  const precisaoSim = div(vn, vn + fn); const recallSim = div(vn, vn + fp);
  return {
    acuracia: r3(div(vp + vn, reais.length)),
    precisao: r3(precisao), recall: r3(recall), f1: r3(div(2 * precisao * recall, precisao + recall)),
    por_classe: {
      nao: { precisao: r3(precisao), recall: r3(recall), f1: r3(div(2 * precisao * recall, precisao + recall)), suporte: vp + fn },
      sim: { precisao: r3(precisaoSim), recall: r3(recallSim), f1: r3(div(2 * precisaoSim * recallSim, precisaoSim + recallSim)), suporte: vn + fp },
    },
    matriz_confusao: {
      legenda: 'linhas = classe real; colunas = classe prevista; ordem [sim, nao]',
      rotulos: [NEG, POS],
      valores: [[vn, fp], [fn, vp]],
      vn, fp, fn, vp,
    },
  };
}

// ----------------------------- avaliação -----------------------------
const cTreino = d.preparacao.treino.classes;
const classeBase = cTreino[POS] > cTreino[NEG] ? POS : NEG;
const reais = d.teste.map((r) => r[ALVO]);
const folhas = d.teste.map((r) => folhaDe(arvore, r));
const previstos = folhas.map((f) => f.classe);
const mArvore = metricas(reais, previstos);
const mBase = metricas(reais, d.teste.map(() => classeBase));
const accTreino = r3(div(d.treino.filter((r) => folhaDe(arvore, r).classe === r[ALVO]).length, d.treino.length));
const ganho = r3(mArvore.acuracia - mBase.acuracia);

const veredito = ganho > 0
  ? `A árvore superou a linha de base: acurácia ${mArvore.acuracia} contra ${mBase.acuracia} (+${r3(ganho * 100)} p.p.). A linha de base (sempre "${classeBase}") não identifica nenhuma demanda em risco (recall da classe "nao" = ${mBase.recall}); a árvore identifica ${r3(mArvore.recall * 100)}% delas.`
  : `A árvore NÃO superou a linha de base (acurácia ${mArvore.acuracia} contra ${mBase.acuracia}). Possíveis causas: base pequena, atributos pouco informativos ou ruído nos rótulos.`;

// exemplos reais de acertos e erros (para o relatório)
const ex = d.teste.map((r, i) => ({
  id_demanda: r.id_demanda, real: r[ALVO], previsto: previstos[i],
  produto: r.produto, uf_origem: r.uf_origem, destino: r.destino, distancia_km: r.distancia_km, frete_ton: r.frete_ton,
  frete_por_km: r.frete_por_km, saldo_ton: r.saldo_ton, balanca: r.balanca, estrada_chao_km: r.estrada_chao_km,
  antecedencia_h: r.antecedencia_h, folha_n: folhas[i].n, folha_sim: folhas[i].contagem.sim, folha_nao: folhas[i].contagem.nao,
}));
const exemplos = {
  acertos: ex.filter((e) => e.real === e.previsto).slice(0, 4),
  falsos_positivos: ex.filter((e) => e.real === NEG && e.previsto === POS).slice(0, 3),   // previu "nao", era "sim"
  falsos_negativos: ex.filter((e) => e.real === POS && e.previsto === NEG).slice(0, 3),   // previu "sim", era "nao"
};

const metricasFinais = {
  conjunto_avaliado: `teste: ${d.teste.length} demandas históricas nunca vistas no treino`,
  classe_positiva: 'nao (não atendida)',
  arvore: mArvore,
  linha_base: { regra: `prever sempre "${classeBase}" (classe mais frequente no treino)`, classe: classeBase, ...mBase },
  acuracia_treino: accTreino,
  diferenca_treino_teste: r3(accTreino - mArvore.acuracia),
  ganho_sobre_linha_base: ganho,
  superou_linha_base: ganho > 0,
  veredito,
  observacao: `Com ${d.teste.length} demandas de teste, cada erro altera a acurácia em ~${r3(100 / d.teste.length)} p.p.: os números são indicativos, não definitivos.`,
  validacao_cruzada: d.modelo.validacao_cruzada,
  experimento_vazamento: d.modelo.experimento_vazamento,
  exemplos,
};

const agora = new Date();
const versao = `cart-gini-${agora.toISOString().slice(0, 19).replace(/[-:T]/g, '')}`;

return [{ json: {
  registro_modelo: {
    versao,
    algoritmo: d.modelo.algoritmo,
    parametros: d.modelo.parametros,
    atributos: d.atributos,
    arvore,
    arvore_texto: d.modelo.arvore_texto,
    importancias: d.modelo.importancias,
    metricas: { ...metricasFinais, estrutura: { nos: d.modelo.nos, folhas: d.modelo.folhas, profundidade_real: d.modelo.profundidade_real } },
    preparacao: d.preparacao,
    n_treino: d.treino.length,
    n_teste: d.teste.length,
  },
  resumo: {
    versao,
    registros: d.preparacao.registros_utilizados,
    treino: d.treino.length, teste: d.teste.length,
    profundidade: d.modelo.parametros.profundidade_maxima,
    folhas: d.modelo.folhas,
    acuracia: mArvore.acuracia, precisao_nao: mArvore.precisao, recall_nao: mArvore.recall, f1_nao: mArvore.f1,
    acuracia_linha_base: mBase.acuracia,
    acuracia_com_vazamento: d.modelo.experimento_vazamento.acuracia_teste,
    veredito,
  },
} }];

// =====================================================================
// BLOCO 10 | CASOS DE TESTE (execução manual no editor do n8n)
// Gera solicitações de TESTE (canal "teste", ambiente "teste") que percorrem o mesmo
// pipeline das demandas reais. Ficam gravadas no banco, mas o dashboard IGNORA o
// ambiente "teste" — nenhum número fictício aparece nos indicadores.
// Os dados abaixo são EXEMPLOS FICTÍCIOS criados para teste (não são do dataset).
// =====================================================================

const execucao = new Date().toISOString();
const casos = [
  { cenario: 'geral_financeiro', tipo_informado: 'geral', solicitante: { nome: 'Teste Financeiro', email: 'teste.financeiro@example.com' },
    assunto: 'Segunda via de boleto', texto: 'Preciso da segunda via do boleto com vencimento nesta semana.' },
  { cenario: 'geral_cadastro', solicitante: { nome: 'Teste Cadastro', telefone: '42999990000' },
    assunto: '', texto: 'Gostaria de atualizar os dados do meu cadastro e do contrato.' },
  { cenario: 'logistica_campos', tipo_informado: 'logistica', solicitante: { nome: 'Teste Frete', email: 'teste.frete@example.com' },
    campos_brutos: { produto: 'SOJA', uf_origem: 'PR', destino: 'Paranaguá', distancia_km: '560', frete_ton: '150', saldo_ton: '2500', balanca: '25m', estrada_chao_km: '0', antecedencia_h: '72' } },
  { cenario: 'logistica_texto_livre', solicitante: { nome: 'Teste Texto Livre', email: 'teste.texto@example.com' },
    texto: 'Preciso transportar milho do PR para Toledo, 400 km, frete de R$ 75 por tonelada, saldo de 1.800 toneladas, balança 20m, 15 km de estrada de chão, 24 horas de antecedência.' },
  { cenario: 'logistica_incompleta', solicitante: { nome: 'Teste Incompleto', email: 'teste.incompleto@example.com' },
    texto: 'Preciso transportar soja de MS para Paranaguá.' },
  { cenario: 'logistica_invalida', tipo_informado: 'logistica', solicitante: { nome: 'Teste Inválido', email: 'email-invalido' },
    campos_brutos: { produto: 'MILHO', uf_origem: 'XX', destino: 'Maringá', distancia_km: '-5', frete_ton: '90', saldo_ton: '1000', balanca: '40m', estrada_chao_km: '0', antecedencia_h: '48' } },
];

return casos.map((c, i) => ({ json: {
  canal: 'teste',
  ambiente: 'teste',
  chave_evento: `teste:${execucao}:${i}`,
  solicitante: c.solicitante,
  tipo_informado: c.tipo_informado || null,
  assunto: c.assunto || '',
  texto: c.texto || '',
  campos_brutos: c.campos_brutos || {},
  dados_originais: { cenario: c.cenario, ...c },
  resposta: { via: 'teste' },
} }));
